import React, { useEffect, useMemo, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import './styles.css';
import {
  createUniverse, hydrateUniverse, RARITY, SERIES_META, countryFlag, countryIso2, getDriver, getTeam, getStaff,
  getEngine, getSponsor, getMainBrand, SCHEMA_VERSION, currentDriverRating, effectiveDriverSkill,
} from './data.js';
import {
  SESSION_TEMPLATES, simulateWeeks, simulateToSeasonEnd,
  advanceToNextSeason, driverStandings, constructorStandings, powerRankings,
  goatLeaderboard, circuitFitRanking, sponsorFit,
} from './sim.js';
import { saveSlot, loadSlot, deleteSlot, listSlots, exportUniverse, importUniverse } from './storage.js';

const SERIES_ORDER=['F1','F2','F3','F4','FE','WEC'];
const RARITY_ORDER={Generational:6,Legend:5,Epic:4,Rare:3,Uncommon:2,Common:1};
const NAV=[
  ['home','Home'],['competitions','Competitions'],['schedule','Schedule'],['results','Results'],
  ['drivers','Drivers'],['teams','Teams'],['paddock','Paddock'],['almanac','Almanac'],['more','More'],
];
const clamp=(value,min,max)=>Math.max(min,Math.min(max,value));
const avg=(values)=>values.length?values.reduce((sum,value)=>sum+value,0)/values.length:0;
const money=(value)=>`${Number(value||0)<0?'-':''}$${Math.abs(Math.round(value||0))}m`;
const careerMultiplier=(driver)=>driver?.careerCurve?.[driver.curveIndex]||driver?.careerMultiplier||.9;
const currentRating=(driver)=>currentDriverRating(driver);
const seriesName=(series)=>SERIES_META[series]?.name||series;
const yearLabel=(year)=>{const value=Number(year)||1;return `Year ${value>=2000?Math.max(1,value-2025):value}`;};
const relationshipLabel=(score)=>score>=60?'Close friends':score>=25?'Mutual respect':score<=-60?'Bitter rivals':score<=-25?'Rivals':'Neutral';
const relationshipClass=(score)=>score<=-60?'bitter':score<=-25?'negative':score>=60?'close':score>=25?'positive':'neutral';

function Flag({driver=null,country='',code=''}){
  const source=code||driver?.countryCode||country||driver?.country||'';const iso2=countryIso2(source);const label=code||driver?.countryCode||iso2;
  return <span className="flag" title={country||driver?.country||label}><b aria-hidden="true" style={{display:'none'}}>{countryFlag(source)}</b><img src={`${import.meta.env.BASE_URL}flags/${iso2.toLowerCase()}.png`} alt={`${country||driver?.country||label} flag`} onError={(event)=>{event.currentTarget.style.display='none';if(event.currentTarget.previousElementSibling)event.currentTarget.previousElementSibling.style.display='inline';}}/><small>{label}</small></span>;
}
function SeatBadge({driver=null,seat=null,team=null}){const raw=seat??driver?.seat??0;const value=(driver?.role==='Test driver'||driver?.role==='Reserve driver')?3:raw;if(!value)return null;const primary=team?.primary||team?.color||'#555';const secondary=team?.secondary||team?.color||'#888';return <span className="seat-badge" style={{'--seat-team':primary,'--seat-team-2':secondary}} title={value===1?'First driver':value===2?'Second driver':value===3?'Test / reserve driver':`Driver ${value}`}><i>{value}</i></span>}
function RarityTag({rarity}){return <span className={`rarity rarity-${String(rarity).toLowerCase()}`} style={{'--rarity':RARITY[rarity]?.color}}>{rarity}</span>}
function SeriesTag({series,role=null}){return <span className="series-tag" style={{'--series':SERIES_META[series]?.color||'#777'}}>{role==='Test driver'?'TEST':role==='Free agent'?'FREE':role==='Retired'?'RET':series}</span>}
function TeamStripe({team}){const primary=team?.primary||team?.color||'#444';const secondary=team?.secondary||team?.color||'#888';return <span className="team-stripe" style={{background:`linear-gradient(${primary},${secondary})`}}/>}
function Pill({children,active,onClick}){return <button className={`pill ${active?'active':''}`} onClick={onClick}>{children}</button>}
function Panel({title,eyebrow,children,action=null,className=''}){return <section className={`panel ${className}`}><header><div>{eyebrow&&<small>{eyebrow}</small>}<h2>{title}</h2></div>{action}</header>{children}</section>}
function PageTitle({eyebrow,title,subtitle,action=null}){return <div className="page-title"><div><small>{eyebrow}</small><h1>{title}</h1><p>{subtitle}</p></div>{action}</div>}
function Empty({title,body}){return <div className="empty"><b>F1</b><h3>{title}</h3><p>{body}</p></div>}
function Progress({label,value}){return <div className="progress"><span>{label}</span><i><b style={{width:`${clamp(value,0,100)}%`}}/></i><strong>{Math.round(value)}</strong></div>}

function UniverseHub({slots,setSlots,onLoad,onCreate,onImport}){
  const [name,setName]=useState('My F1 Universe');
  const [busy,setBusy]=useState(false);
  const inputRef=useRef(null);
  const create=async(slot)=>{setBusy(true);try{await onCreate(slot,name.trim()||`Universe ${slot}`);}finally{setBusy(false);}};
  const remove=async(slot)=>{if(!window.confirm(`Delete Universe Slot ${slot}? This cannot be undone.`))return;await deleteSlot(slot);setSlots(await listSlots());};
  const importFile=async(event)=>{const file=event.target.files?.[0];if(!file)return;setBusy(true);try{await onImport(file);}finally{setBusy(false);event.target.value='';}};
  return <div className="launcher">
    <div className="launcher-grid-bg"/>
    <header className="launcher-head"><div className="f1-logo">F1</div><div><small>WORLD CHRONICLE</small><h1>Choose a universe</h1></div></header>
    <div className="launcher-intro"><p>Every slot is a separate procedural motorsport history: F4 prospects, feeder champions, F1 dynasties, team takeovers, sponsors, weather, records and GOAT debates.</p><label>New universe name<input value={name} onChange={(event)=>setName(event.target.value)} maxLength={38}/></label></div>
    <div className="slot-grid">{[1,2,3].map((slot)=>{const meta=slots.find((item)=>item.slot===slot);return <article className={`slot-card ${meta?'occupied':'empty-slot'}`} key={slot}>
      <div className="slot-number">SLOT {slot}</div>
      {meta?<><h2>{meta.label}</h2><div className="slot-season"><b>{yearLabel(meta.year)}</b><span>{meta.phase}<br/>Round {Math.min((meta.round||0)+1,24)}</span></div><small>Last played {new Date(meta.updatedAt).toLocaleString()} · schema v{meta.schemaVersion||'legacy'}</small>{(meta.schemaVersion||0)<5&&<p className="legacy-warning">This slot belongs to an early prototype and cannot be migrated safely. Export it from the old build or delete it before creating a new universe.</p>}<div className="slot-actions"><button className="primary" onClick={()=>onLoad(slot)} disabled={busy||(meta.schemaVersion||0)<5}>Load universe</button><button className="danger" onClick={()=>remove(slot)} disabled={busy}>Delete</button></div></>:<><div className="empty-mark">+</div><h2>Empty universe</h2><p>Generate procedural drivers, staff, sponsors and the complete racing world.</p><button className="primary" onClick={()=>create(slot)} disabled={busy}>Create in Slot {slot}</button></>}
    </article>})}</div>
    <div className="launcher-footer"><button className="outline" onClick={()=>inputRef.current?.click()}>Import universe JSON</button><span>IndexedDB saves · no browser localStorage quota</span></div>
    <input ref={inputRef} hidden type="file" accept="application/json" onChange={importFile}/>
  </div>;
}

function App(){
  const [slots,setSlots]=useState([]);
  const [universe,setUniverse]=useState(null);
  const [currentSlot,setCurrentSlot]=useState(null);
  const [page,setPageState]=useState('home');
  const [selectedDriver,setSelectedDriverState]=useState(null);
  const [selectedTeam,setSelectedTeamState]=useState(null);
  const [selectedEvent,setSelectedEventState]=useState(null);
  const [selectedStaff,setSelectedStaffState]=useState(null);
  const [selectedCompetition,setSelectedCompetition]=useState('F1');
  const [toast,setToast]=useState('');
  const [busy,setBusy]=useState(false);
  const autosaveReady=useRef(false);

  const applyRoute=(route={page:'home'})=>{setPageState(route.page||'home');setSelectedDriverState(route.driver||null);setSelectedTeamState(route.team||null);setSelectedEventState(route.event||null);setSelectedStaffState(route.staff||null);};
  const navigate=(route,replace=false)=>{const hash=route.driver?`#/driver/${route.driver}`:route.team?`#/team/${route.team}`:route.staff?`#/staff/${route.staff}`:route.event?`#/event/${route.event.series}/${route.event.eventId}`:`#/${route.page||'home'}`;window.history[replace?'replaceState':'pushState'](route,'',hash);applyRoute(route);};
  const setPage=(id)=>navigate({page:id});
  const setSelectedDriver=(id)=>id&&navigate({driver:id});
  const setSelectedTeam=(id)=>id&&navigate({team:id});
  const setSelectedStaff=(id)=>id&&navigate({staff:id});
  const setSelectedEvent=(event)=>event&&navigate({event});
  const back=()=>window.history.length>1?window.history.back():navigate({page:'home'},true);

  useEffect(()=>{listSlots().then(setSlots).catch(()=>setSlots([]));const pop=(event)=>applyRoute(event.state||{page:'home'});window.addEventListener('popstate',pop);return()=>window.removeEventListener('popstate',pop);},[]);
  useEffect(()=>{if(!universe||!currentSlot||!universe.settings?.autoSave)return;if(!autosaveReady.current){autosaveReady.current=true;return;}const timer=window.setTimeout(()=>saveSlot(currentSlot,universe,universe.name||`Universe ${currentSlot}`).then(()=>listSlots().then(setSlots)).catch(()=>{}),800);return()=>window.clearTimeout(timer);},[universe,currentSlot]);

  const notify=(message)=>{setToast(message);window.setTimeout(()=>setToast(''),2600);};
  const load=async(slot)=>{const data=await loadSlot(slot);if(!data)return;if((data.schemaVersion||0)<5){window.alert('This save uses an early schema that cannot be migrated safely.');return;}setUniverse(hydrateUniverse(data));setCurrentSlot(slot);navigate({page:'home'},true);autosaveReady.current=false;};
  const create=async(slot,name)=>{const data=createUniverse((Date.now()+slot*101)%2147483000);data.name=name;await saveSlot(slot,data,name);setSlots(await listSlots());setUniverse(hydrateUniverse(data));setCurrentSlot(slot);navigate({page:'home'},true);autosaveReady.current=false;};
  const importSave=async(file)=>{const data=await importUniverse(file);if((data.schemaVersion||0)<5){window.alert('This save uses an early schema that cannot be migrated safely.');return;}const empty=[1,2,3].find((slot)=>!slots.some((item)=>item.slot===slot));if(!empty){notify('Delete a slot before importing.');return;}data.name=data.name||'Imported universe';await saveSlot(empty,data,data.name);setSlots(await listSlots());setUniverse(hydrateUniverse(data));setCurrentSlot(empty);navigate({page:'home'},true);};
  const saveNow=async()=>{if(!universe||!currentSlot)return;await saveSlot(currentSlot,universe,universe.name||`Universe ${currentSlot}`);setSlots(await listSlots());notify(`Saved to Slot ${currentSlot}`);};
  const saveAndExit=async()=>{await saveNow();setUniverse(null);setCurrentSlot(null);applyRoute({page:'home'});autosaveReady.current=false;};
  const perform=(fn,message)=>{setBusy(true);window.setTimeout(()=>{setUniverse((previous)=>fn(previous));setBusy(false);if(message)notify(message);},35);};

  if(!universe)return <UniverseHub slots={slots} setSlots={setSlots} onLoad={load} onCreate={create} onImport={importSave}/>;

  const worldEvents=SERIES_ORDER.flatMap((series)=>competitionCalendar(universe,series).map((event)=>({...event,series}))).filter((event)=>event.status!=='Complete').sort((a,b)=>(a.week||99)-(b.week||99)||a.round-b.round);
  const event=worldEvents[0];
  const week=()=>perform((u)=>simulateWeeks(u,1),'One motorsport week simulated');
  const month=()=>perform((u)=>simulateWeeks(u,4),'Four motorsport weeks simulated');
  const season=()=>window.confirm('Simulate every remaining event in every championship?')&&perform(simulateToSeasonEnd,'All championships completed');
  const nextYear=()=>perform(advanceToNextSeason,`Welcome to ${yearLabel(universe.year+1)}`);
  const leaders=Object.fromEntries(SERIES_ORDER.map((series)=>[series,driverStandings(universe,series)[0]]));
  const pageProps={universe,setUniverse,setPage,setSelectedDriver,setSelectedTeam,setSelectedEvent,setSelectedStaff,selectedCompetition,setSelectedCompetition,week,month,season,nextYear,busy,saveNow,saveAndExit,currentSlot};
  const normalContent={home:<Home {...pageProps}/>,competitions:<Competitions {...pageProps}/>,schedule:<Schedule {...pageProps}/>,results:<Results {...pageProps}/>,drivers:<Drivers {...pageProps}/>,teams:<Teams {...pageProps}/>,paddock:<Paddock {...pageProps}/>,almanac:<Almanac {...pageProps}/>,more:<More {...pageProps}/>}[page];
  const content=selectedDriver?<DriverPage universe={universe} driver={getDriver(universe,selectedDriver)} back={back} openTeam={setSelectedTeam} openStaff={setSelectedStaff} openDriver={setSelectedDriver}/>:selectedTeam?<TeamPage universe={universe} team={getTeam(universe,selectedTeam)} back={back} openDriver={setSelectedDriver} openStaff={setSelectedStaff}/>:selectedStaff?<StaffPage universe={universe} member={getStaff(universe,selectedStaff)} back={back} openTeam={setSelectedTeam} openDriver={setSelectedDriver}/>:selectedEvent?<EventPage universe={universe} selection={selectedEvent} back={back} openDriver={setSelectedDriver} openTeam={setSelectedTeam}/>:normalContent;

  return <div className="app-shell">
    <div className="global-sim-bar"><span><b>{yearLabel(universe.year)}</b> · Week {universe.currentWeek||1} · {universe.phase}</span><div>{universe.phase==='Season complete'?<button className="primary" onClick={nextYear} disabled={busy}>Move to {yearLabel(universe.year+1)}</button>:<><button onClick={week} disabled={busy}>+1</button><button onClick={month} disabled={busy}>+4</button><button className="primary" onClick={season} disabled={busy}>Year end</button></>}</div></div>
    <header className="topbar"><button className="brand" onClick={()=>setPage('home')}><b>F1</b><span>WORLD CHRONICLE</span></button><nav>{NAV.map(([id,label])=><button key={id} className={!selectedDriver&&!selectedTeam&&!selectedEvent&&!selectedStaff&&page===id?'active':''} onClick={()=>setPage(id)}>{label}</button>)}</nav><div className="top-actions"><button onClick={saveNow}>Save</button><button onClick={saveAndExit}>Slots</button></div></header>
    <div className="ticker"><div><small>WEEK {universe.currentWeek||1} · {event?.series||'WORLD'}</small><b>{event?.country||'Season complete'}</b><span>{event?.name||'Run the off-season'}</span></div><div className="ticker-series">{['F1','F2','F4'].map((series)=><span key={series}><small>{series}</small><b>{leaders[series]?.name||'—'}</b></span>)}</div></div>
    <main>{content}</main>{toast&&<div className="toast">{toast}</div>}
  </div>;
}

function Home({universe,setPage,setSelectedDriver,setSelectedTeam,setSelectedEvent,week,month,season,busy}){
  const allEvents=SERIES_ORDER.flatMap((series)=>competitionCalendar(universe,series).map((event)=>({...event,series}))).sort((a,b)=>(a.week||99)-(b.week||99)||a.round-b.round);
  const upcoming=allEvents.filter((event)=>event.status!=='Complete').slice(0,8);
  const leaders=SERIES_ORDER.map((series)=>({series,driver:driverStandings(universe,series)[0]}));
  const prospects=universe.drivers.filter((driver)=>driver.active&&['F2','F3','F4'].includes(driver.series)&&['Generational','Legend'].includes(driver.rarity)).sort((a,b)=>RARITY_ORDER[b.rarity]-RARITY_ORDER[a.rarity]||currentRating(b)-currentRating(a)).slice(0,6);
  const headline=upcoming[0];
  return <section className="page"><div className="hero world-hero"><div className="hero-copy"><small>{universe.name.toUpperCase()} · {yearLabel(universe.year)} · WEEK {universe.currentWeek||1}</small><h1>Motorsport<br/><em>World</em></h1><p>{headline?`${headline.series} travels next to ${headline.country} for ${headline.name}.`:'Every championship is complete.'} The universe advances by time, so F4, F3, F2, Formula E, WEC and F1 events all happen on their own calendars.</p><div className="actions"><button className="primary" onClick={week} disabled={busy}>Simulate 1 week</button><button className="outline" onClick={month} disabled={busy}>Simulate 4 weeks</button><button className="outline" onClick={season} disabled={busy}>To year end</button></div></div><div className="hero-card world-next"><small>NEXT WORLD EVENT</small><SeriesTag series={headline?.series||'F1'}/><Flag country={headline?.country}/><h2>{headline?.name||'Off-season'}</h2><p>Week {headline?.week||'—'} · Round {headline?.round||'—'}</p><button className="link" onClick={()=>headline&&setSelectedEvent({series:headline.series,eventId:headline.id,circuitId:headline.circuitId||headline.id})}>Open event page ›</button></div></div>
  <div className="dashboard"><Panel title="World calendar" eyebrow="NEXT EIGHT EVENTS" className="span-2" action={<button className="link" onClick={()=>setPage('schedule')}>Full schedule</button>}><div className="world-calendar-strip">{upcoming.map((event)=><button key={`${event.series}-${event.id}`} onClick={()=>setSelectedEvent({series:event.series,eventId:event.id,circuitId:event.circuitId||event.id})}><SeriesTag series={event.series}/><b>W{event.week}</b><Flag country={event.country}/><span>{event.name}<small>{event.city}</small></span></button>)}</div></Panel>
  <Panel title="Championship leaders" eyebrow="ALL COMPETITIONS"><div className="leader-list compact">{leaders.map(({series,driver})=><button key={series} onClick={()=>driver&&setSelectedDriver(driver.id)}><SeriesTag series={series}/><Flag driver={driver}/><span><b>{driver?.name||'—'}</b><small>{driver?.season.points||0} points</small></span></button>)}</div></Panel>
  <Panel title="Elite prospects" eyebrow="F4 · F3 · F2" className="span-2" action={<button className="link" onClick={()=>setPage('drivers')}>All drivers</button>}><div className="prospect-grid">{prospects.map((driver)=><button key={driver.id} onClick={()=>setSelectedDriver(driver.id)}><div><SeriesTag series={driver.series}/><RarityTag rarity={driver.rarity}/></div><Flag driver={driver}/><h3>{driver.name}</h3><p>{driver.age} years · {getTeam(universe,driver.teamId)?.name}</p><span><b>{currentRating(driver)}</b>current ability</span></button>)}</div></Panel>
  <Panel title="Teams to watch" eyebrow="FINANCES + CAR"><div className="leader-list compact">{universe.teams.slice().sort((a,b)=>(b.finances.projectedBalance||0)-(a.finances.projectedBalance||0)).slice(0,5).map((team)=><button key={team.id} onClick={()=>setSelectedTeam(team.id)}><TeamStripe team={team}/><span><b>{team.name}</b><small>{money(team.finances.projectedBalance)} balance · car {Math.round(team.baseline)}</small></span></button>)}</div></Panel></div></section>;
}

function CompetitionRaceTable({universe,series,openEvent}){
  const calendar=competitionCalendar(universe,series);
  const records=competitionResults(universe,series);
  return <div className="competition-race-table"><div className="competition-race-head"><b>Rnd</b><b>Grand Prix / event</b><b>Winner</b><b>Second</b><b>Third</b><b>Winning team</b><b>Pole</b><b>Fastest lap</b></div>{calendar.map((event)=>{const record=records.find((item)=>item.eventId===event.id);const podium=record?.podium||[];const winner=getDriver(universe,record?.winnerId);const second=getDriver(universe,podium[1]?.driverId);const third=getDriver(universe,podium[2]?.driverId);const pole=getDriver(universe,record?.poleId);const fastest=getDriver(universe,record?.fastestLapDriverId);const team=getTeam(universe,record?.teamWinnerId);return <button key={event.id} onClick={()=>openEvent({series,eventId:event.id,circuitId:event.circuitId||event.id})}><strong>{event.round}</strong><span><Flag country={event.country}/><b>{event.name}</b><small>Week {event.week} · {event.status}</small></span><span>{winner?.name||'—'}</span><span>{second?.name||'—'}</span><span>{third?.name||'—'}</span><span>{team?.name||'—'}</span><span>{pole?.name||'—'}</span><span>{fastest?.name||'—'}<small>{record?lapDisplay(record.fastestLapTime):''}</small></span></button>})}</div>
}

function Competitions({universe,selectedCompetition,setSelectedCompetition,setSelectedDriver,setSelectedTeam,setSelectedEvent}){
  const [tab,setTab]=useState('Overview');
  const series=selectedCompetition;
  const standings=driverStandings(universe,series);
  const teams=teamStandings(universe,series);
  const currentResults=competitionResults(universe,series);
  const history=[...universe.seasonArchive].reverse().map((season)=>({year:season.year,...(season.series?.[series]||{})})).filter((item)=>item.championId);
  const stats=[...universe.drivers].map((driver)=>{
    const seasons=(driver.career.seasons||[]).filter((item)=>item.series===series);
    const titles=(driver.trophies||[]).filter((trophy)=>trophy.includes(`${series} Champion`)||(series==='F1'&&trophy.includes('Formula 1 World Champion'))).length;
    return {...driver,seriesStarts:seasons.length,seriesPoints:seasons.reduce((sum,item)=>sum+(item.points||0),0)+(driver.series===series?driver.season.points:0),seriesWins:seasons.reduce((sum,item)=>sum+(item.wins||0),0)+(driver.series===series?driver.season.wins:0),seriesTitles:titles};
  }).filter((driver)=>driver.seriesStarts||driver.series===series).sort((a,b)=>b.seriesTitles-a.seriesTitles||b.seriesWins-a.seriesWins||b.seriesPoints-a.seriesPoints);
  const leader=standings[0];
  const latest=currentResults.at(-1);
  const youngest=standings.length?Math.min(...standings.map((driver)=>driver.age)):'—';
  return <section className="page"><PageTitle eyebrow="MOTORSPORT WORLD" title="Competitions" subtitle="Every tier has its own calendar, race archive, standings and permanent history. Follow a driver from F4 through the whole universe."/>
    <div className="competition-picker">{SERIES_ORDER.map((item)=><button key={item} className={series===item?'active':''} style={{'--series':SERIES_META[item].color}} onClick={()=>{setSelectedCompetition(item);setTab('Overview')}}><b>{item}</b><span>{SERIES_META[item].name}</span><small>{driverStandings(universe,item).length} drivers</small></button>)}</div>
    <div className="tab-row">{['Overview','Current Year','Standings','History','Stats'].map((item)=><Pill key={item} active={tab===item} onClick={()=>setTab(item)}>{item}</Pill>)}</div>
    {tab==='Overview'&&<div className="two-col"><Panel title={`${seriesName(series)} leader`} eyebrow={`${yearLabel(universe.year)} OVERVIEW`}>{leader?<div className="champion-card"><div><SeriesTag series={series}/><RarityTag rarity={leader.rarity}/></div><Flag driver={leader}/><h2>{leader.name}</h2><p>{getTeam(universe,leader.teamId)?.name} · {leader.age} years · {leader.style}</p><strong>{leader.season.points} points</strong><button className="outline" onClick={()=>setSelectedDriver(leader.id)}>Driver profile</button></div>:<Empty title="No active field" body="This competition currently has no active drivers."/>}</Panel><Panel title="Championship snapshot" eyebrow="LIVE"><div className="podium-list">{standings.slice(0,3).map((driver,index)=><button key={driver.id} onClick={()=>setSelectedDriver(driver.id)}><strong>P{index+1}</strong><Flag driver={driver}/><span><b>{driver.name}</b><small>{getTeam(universe,driver.teamId)?.name}</small></span><em>{driver.season.points}</em></button>)}</div><div className="competition-facts"><span><b>{teams[0]?.name||'—'}</b>Leading team</span><span><b>{latest?getDriver(universe,latest.winnerId)?.name||'—':'—'}</b>Most recent winner</span><span><b>{youngest}</b>Youngest</span></div></Panel></div>}
    {tab==='Current Year'&&<Panel title={`${yearLabel(universe.year)} race-by-race`} eyebrow={`${series} CALENDAR`}><CompetitionRaceTable universe={universe} series={series} openEvent={setSelectedEvent}/></Panel>}
    {tab==='Standings'&&<div className="competition-current"><Panel title="Driver standings" eyebrow={`${yearLabel(universe.year)} ${series}`}><StandingsTable universe={universe} rows={standings} openDriver={setSelectedDriver}/></Panel><Panel title="Team standings" eyebrow="CONSTRUCTORS / ENTRANTS"><div className="team-table">{teams.map((team,index)=><button key={team.id} onClick={()=>setSelectedTeam(team.id)}><strong>{index+1}</strong>{series==='F1'?<TeamStripe team={team}/>:<i style={{background:team.color}}/>}<span><b>{team.name}</b><small>{team.wins||team.seasonWins||0} wins</small></span><em>{team.points??team.seasonPoints??0}</em></button>)}</div></Panel><Panel title="Season leaders" eyebrow="STATS"><div className="stat-leaders">{[
      ['Wins',[...standings].sort((a,b)=>b.season.wins-a.season.wins)[0],d=>d.season.wins],['Poles',[...standings].sort((a,b)=>b.season.poles-a.season.poles)[0],d=>d.season.poles],['Podiums',[...standings].sort((a,b)=>b.season.podiums-a.season.podiums)[0],d=>d.season.podiums],['Current ability',[...standings].sort((a,b)=>currentRating(b)-currentRating(a))[0],currentRating]
    ].map(([label,driver,value])=><button key={label} onClick={()=>driver&&setSelectedDriver(driver.id)}><small>{label}</small><b>{driver?.name||'—'}</b><em>{driver?value(driver):'—'}</em></button>)}</div></Panel></div>}
    {tab==='History'&&(history.length?<Panel title={`${seriesName(series)} championship history`} eyebrow="TOP THREE + CONSTRUCTOR"><CompetitionHistoryTable universe={universe} history={history} series={series}/></Panel>:<Empty title="The first season is still being written" body={`Complete ${yearLabel(universe.year)} to create the permanent ${series} history.`}/>) }
    {tab==='Stats'&&<div className="record-card-grid"><LeaderCard title="Most titles" rows={[...stats].sort((a,b)=>b.seriesTitles-a.seriesTitles||b.seriesWins-a.seriesWins).slice(0,5)} value={(driver)=>`${driver.seriesTitles} titles`} onOpen={setSelectedDriver}/><LeaderCard title="Most race wins" rows={[...stats].sort((a,b)=>b.seriesWins-a.seriesWins||b.seriesPoints-a.seriesPoints).slice(0,5)} value={(driver)=>`${driver.seriesWins} wins`} onOpen={setSelectedDriver}/><LeaderCard title="Most races" rows={[...stats].sort((a,b)=>b.seriesStarts-a.seriesStarts||b.seriesPoints-a.seriesPoints).slice(0,5)} value={(driver)=>`${driver.seriesStarts} seasons`} onOpen={setSelectedDriver}/><LeaderCard title="Most points" rows={[...stats].sort((a,b)=>b.seriesPoints-a.seriesPoints).slice(0,5)} value={(driver)=>`${driver.seriesPoints} pts`} onOpen={setSelectedDriver}/></div>}
  </section>;
}

function CompetitionHistoryTable({universe,history,series}){
  return <div className="competition-history-table"><div className="competition-history-head"><b>Year</b><b>Champion · team</b><b>Pts</b><b>Second · team</b><b>Pts</b><b>Third · team</b><b>Pts</b><b>Winning team</b><b>Team pts</b></div>{history.map((season)=>{const top=season.standings||[];const first=top[0];const second=top[1];const third=top[2];const teamName=(row)=>row?.teamName||getTeam(universe,row?.teamId)?.name||'—';const winnerTeam=season.teamChampionName||season.teams?.[0]?.name||'—';const teamPoints=season.teamChampionPoints??season.teams?.[0]?.points??'—';return <div key={`${series}-${season.year}`}><strong>{yearLabel(season.year)}</strong><span><b>{first?.name||season.championName||'—'}</b><small>{teamName(first)}</small></span><em>{first?.points??season.championPoints??'—'}</em><span><b>{second?.name||'—'}</b><small>{teamName(second)}</small></span><em>{second?.points??'—'}</em><span><b>{third?.name||'—'}</b><small>{teamName(third)}</small></span><em>{third?.points??'—'}</em><span><b>{winnerTeam}</b></span><strong>{teamPoints}</strong></div>})}</div>;
}

function StandingsTable({universe,rows,openDriver}){return <div className="standings-table">{rows.map((driver,index)=>{const team=getTeam(universe,driver.teamId);return <button key={driver.id} onClick={()=>openDriver(driver.id)}><strong>{index+1}</strong><Flag driver={driver}/><RarityTag rarity={driver.rarity}/><SeatBadge driver={driver} team={team}/><TeamStripe team={team}/><span><b>{driver.name}</b><small>{team?.name||driver.role} · {driver.trackSpecialty}</small></span><em>{driver.season.wins} W</em><em>{driver.season.podiums} P</em><b>{driver.season.points}</b></button>})}</div>}

function teamStandings(universe,series){
  if(series==='F1')return constructorStandings(universe).map((team)=>({...team,points:team.seasonPoints,wins:team.seasonWins}));
  return (universe.feederTeams?.[series]||[]).map((team)=>({...team,points:team.points??team.season?.points??0,wins:team.wins??team.season?.wins??0})).sort((a,b)=>b.points-a.points||b.wins-a.wins||(b.baseline||b.rating||0)-(a.baseline||a.rating||0));
}
function competitionCalendar(universe,series){return universe.competitionCalendars?.[series]||(series==='F1'?universe.calendar:[])}
function competitionResults(universe,series){return universe.competitionEventResults?.[series]||[]}
function Schedule({universe,setSelectedEvent,week,month,season,busy}){
  const [series,setSeries]=useState('All');
  const events=(series==='All'?SERIES_ORDER.flatMap((item)=>competitionCalendar(universe,item).map((event)=>({...event,series:item}))):competitionCalendar(universe,series).map((event)=>({...event,series}))).sort((a,b)=>(a.week||99)-(b.week||99)||a.round-b.round);
  return <section className="page"><PageTitle eyebrow={`${yearLabel(universe.year)} · WEEK ${universe.currentWeek||1}`} title="World schedule" subtitle="One shared motorsport calendar. Simulating time completes every F4, F3, F2, Formula E, WEC and F1 event scheduled inside that window." action={<div className="simulation-actions"><button onClick={week} disabled={busy}>+1 week</button><button onClick={month} disabled={busy}>+4 weeks</button><button className="danger" onClick={season} disabled={busy}>End of year</button></div>}/><div className="tab-row scroll"><Pill active={series==='All'} onClick={()=>setSeries('All')}>All</Pill>{SERIES_ORDER.map((item)=><Pill key={item} active={series===item} onClick={()=>setSeries(item)}>{item}</Pill>)}</div><div className="calendar-grid world-grid">{events.map((event)=><button key={`${event.series}-${event.id}`} className={`calendar-card ${event.status?.toLowerCase()} ${(event.week||99)===(universe.currentWeek||1)?'next':''}`} onClick={()=>setSelectedEvent({series:event.series,eventId:event.id,circuitId:event.circuitId||event.id})}><header><SeriesTag series={event.series}/><small>WEEK {event.week} · ROUND {event.round}</small><Flag country={event.country}/></header><h2>{event.country}</h2><p>{event.city} · {event.name}</p><div className="circuit-tags"><span>{event.rain}% rain · {event.temp}°C</span><span>{event.traits?.high>=88?'High-speed':event.traits?.low>=86?'Technical':event.traits?.straight>=90?'Power':event.traits?.street>=85?'Street':'Balanced'}</span><span>{event.status}</span></div></button>)}</div></section>;
}

function Results({universe,setSelectedDriver,setSelectedEvent}){
  const [series,setSeries]=useState('F1');const records=[...competitionResults(universe,series)].reverse();
  return <section className="page"><PageTitle eyebrow={`${yearLabel(universe.year)} MOTORSPORT WORLD`} title="Results" subtitle="F1, the feeder ladder, Formula E and WEC all preserve complete event weekends. Open a result for Friday practice, Q1–Q3, race classification, circuit history and records."/><div className="competition-picker compact-picker">{SERIES_ORDER.map((item)=><button key={item} className={series===item?'active':''} style={{'--series':SERIES_META[item].color}} onClick={()=>setSeries(item)}><b>{item}</b><span>{SERIES_META[item].name}</span><small>{competitionResults(universe,item).length} results</small></button>)}</div>{records.length?<div className="result-grid">{records.map((record)=>{const winner=getDriver(universe,record.winnerId);const event=record.event||competitionCalendar(universe,series).find((item)=>item.id===record.eventId);return <Panel key={record.id} title={event?.name||`${event?.country} event`} eyebrow={`${series} · ROUND ${record.round}`} action={<button className="link" onClick={()=>setSelectedEvent({series,eventId:record.eventId,circuitId:record.circuitId})}>Open event ›</button>}><div className="result-summary"><span><small>WINNER</small><button onClick={()=>setSelectedDriver(winner?.id)}><Flag driver={winner}/><SeatBadge driver={winner} team={getTeam(universe,winner?.teamId)}/><b>{winner?.name}</b></button></span><span><small>POLE / WEATHER</small><b>{getDriver(universe,record.poleId)?.name||'—'}</b><em>{record.weather?.qualifying||'—'} {record.weather?.qualifyingTemperature!=null?`${record.weather.qualifyingTemperature}°C`:''} → {record.weather?.race||'—'} {record.weather?.raceTemperature!=null?`${record.weather.raceTemperature}°C`:''}</em></span></div><div className="mini-standings">{record.podium?.map((podium)=>{const driver=getDriver(universe,podium.driverId);const team=getTeam(universe,podium.teamId);return <button key={podium.driverId} onClick={()=>setSelectedDriver(driver?.id)}><strong>{podium.position}</strong><Flag driver={driver}/><SeatBadge driver={driver} team={team}/><span>{driver?.name}<small>{team?.name}</small></span></button>})}</div></Panel>})}</div>:<Empty title={`No ${series} results yet`} body="Simulate race weekends to begin this competition's event archive."/>}</section>
}

function Drivers({universe,setSelectedDriver}){
  const [scope,setScope]=useState('All');const [rarity,setRarity]=useState('All');const [query,setQuery]=useState('');const [sort,setSort]=useState('Current value');
  const drivers=useMemo(()=>universe.drivers.filter((driver)=>{
    const scopeMatch=scope==='All'||(scope==='Active'&&driver.active&&driver.role!=='Retired')||scope===driver.series||(scope==='Free Agents'&&driver.role==='Free agent')||(scope==='Test Drivers'&&driver.role==='Test driver')||(scope==='Retired'&&(!driver.active||driver.role==='Retired'));
    const rarityMatch=rarity==='All'||driver.rarity===rarity;const text=`${driver.name} ${driver.country} ${getTeam(universe,driver.teamId)?.name||''}`.toLowerCase();return scopeMatch&&rarityMatch&&text.includes(query.toLowerCase());
  }).sort((a,b)=>sort==='Points'?b.season.points-a.season.points:sort==='Age'?a.age-b.age:sort==='Rarity'?RARITY_ORDER[b.rarity]-RARITY_ORDER[a.rarity]||currentRating(b)-currentRating(a):currentRating(b)-currentRating(a)),[universe,scope,rarity,query,sort]);
  return <section className="page"><PageTitle eyebrow={`${universe.drivers.length} PEOPLE`} title="Drivers" subtitle="The driver database is the whole universe: F1, the complete ladder, Formula E, WEC, free agents, test drivers and retired careers."/><div className="driver-controls"><div className="tab-row scroll">{['All','Active','F1','F2','F3','F4','FE','WEC','Free Agents','Test Drivers','Retired'].map((item)=><Pill key={item} active={scope===item} onClick={()=>setScope(item)}>{item}</Pill>)}</div><input placeholder="Search driver, country or team" value={query} onChange={(event)=>setQuery(event.target.value)}/><select value={rarity} onChange={(event)=>setRarity(event.target.value)}><option>All</option>{Object.keys(RARITY).map((item)=><option key={item}>{item}</option>)}</select><select value={sort} onChange={(event)=>setSort(event.target.value)}><option>Current value</option><option>Points</option><option>Age</option><option>Rarity</option></select></div><div className="driver-count">Showing {drivers.length} drivers</div><div className="driver-table">{drivers.map((driver)=><button key={driver.id} onClick={()=>setSelectedDriver(driver.id)}><SeriesTag series={driver.series} role={driver.role}/><Flag driver={driver}/><RarityTag rarity={driver.rarity}/><SeatBadge driver={driver} team={getTeam(universe,driver.teamId)}/><span className="driver-name"><b>{driver.name}</b><small>{driver.age} · {driver.trackSpecialty}</small></span><span><TeamStripe team={getTeam(universe,driver.teamId)}/><b>{getTeam(universe,driver.teamId)?.name||driver.role}</b><small>{driver.country}</small></span><em><b>{currentRating(driver)}</b>current</em><em><b>{driver.season.points}</b>points</em><em><b>{driver.happiness?.overall||'—'}</b>happy</em><strong>›</strong></button>)}</div></section>;
}

function LiveryCar({team,universe}){
  const brand=getMainBrand(universe,team.mainBrandId);const sponsors=(team.sponsorIds||[]).map((id)=>getSponsor(universe,id)).filter(Boolean);
  return <div className="livery-car" style={{'--primary':team.primary,'--secondary':team.secondary}}><svg viewBox="0 0 860 220" role="img" aria-label={`${team.name} car`}><path className="car-main" d="M22 148 L48 85 L126 78 L155 120 L345 102 L406 77 L510 80 L550 103 L734 118 L818 152 L815 177 L650 177 L615 151 L248 151 L210 181 L70 181 Z"/><path className="car-side" d="M148 126 L347 111 L408 88 L530 89 L575 120 L719 127 L676 151 L243 151 L208 174 L91 174 Z"/><path className="car-secondary" d="M265 132 L410 102 L546 103 L600 129 L520 143 L235 148 Z"/><circle cx="150" cy="165" r="42"/><circle cx="680" cy="165" r="42"/><circle className="hub" cx="150" cy="165" r="18"/><circle className="hub" cx="680" cy="165" r="18"/><text x="380" y="130">{brand?.name||team.short}</text><text className="sponsor-text" x="520" y="146">{sponsors[0]?.name||''}</text></svg></div>;
}

function Teams({universe,setSelectedTeam}){
  const [series,setSeries]=useState('All');const [sort,setSort]=useState('Points');
  const all=[...universe.teams.map((team)=>({...team,series:'F1',displayPoints:team.season?.points??team.seasonPoints??0,displayRevenue:team.finances?.totalIncome||0,displayCar:team.baseline||avg(Object.values(team.car||{}))})),...Object.entries(universe.feederTeams||{}).flatMap(([competition,teams])=>teams.map((team)=>({...team,series:competition,displayPoints:team.points||team.season?.points||0,displayRevenue:team.finances?.totalIncome||team.finances?.income||0,displayCar:team.baseline||team.rating||avg(Object.values(team.carProfile||{}))})))];
  const filtered=all.filter((team)=>series==='All'||team.series===series).sort((a,b)=>sort==='Revenue'?b.displayRevenue-a.displayRevenue:sort==='Car quality'?b.displayCar-a.displayCar:b.displayPoints-a.displayPoints||b.displayCar-a.displayCar);
  return <section className="page"><PageTitle eyebrow={`${all.length} ACTIVE ORGANIZATIONS`} title="Teams" subtitle="Every championship is part of the universe. Filter and compare teams by current points, revenue or car quality, then open a permanent team page."/><div className="team-controls"><div className="tab-row scroll"><Pill active={series==='All'} onClick={()=>setSeries('All')}>All</Pill>{SERIES_ORDER.map((item)=><Pill key={item} active={series===item} onClick={()=>setSeries(item)}>{item}</Pill>)}</div><select value={sort} onChange={(event)=>setSort(event.target.value)}><option>Points</option><option>Revenue</option><option>Car quality</option></select></div><div className="team-grid compact-teams">{filtered.map((team,index)=>{const brand=team.series==='F1'?getMainBrand(universe,team.mainBrandId):null;return <button key={team.id} onClick={()=>setSelectedTeam(team.id)} style={{'--team':team.primary||team.color||SERIES_META[team.series]?.color}}><header><SeriesTag series={team.series}/><strong>{index+1}</strong><span><b>{team.name}</b><small>{brand?`${brand.country} · ${brand.tier}`:team.country}</small></span></header><div className="compact-team-band"/><div className="team-card-stats"><span><b>{team.displayPoints}</b>points</span><span><b>{money(team.displayRevenue)}</b>revenue</span><span><b>{Math.round(team.displayCar)}</b>car</span><span><b>{money(team.finances?.projectedBalance||0)}</b>balance</span></div></button>})}</div></section>;
}

function Paddock({universe,setSelectedDriver,setSelectedTeam,setSelectedStaff}){
  const [view,setView]=useState('Magazine');const [category,setCategory]=useState('All');const [marketSort,setMarketSort]=useState('Newest');const [tier,setTier]=useState('All');
  const categories=['All',...new Set(universe.stories.map((story)=>story.category))];const stories=universe.stories.filter((story)=>category==='All'||story.category===category);
  const openSubject=(story)=>{const ids=story.subjects||[];const driverId=ids.find((id)=>getDriver(universe,id));if(driverId){setSelectedDriver(driverId);return;}const staffId=ids.find((id)=>getStaff(universe,id));if(staffId){setSelectedStaff(staffId);return;}const teamId=ids.find((id)=>getTeam(universe,id));if(teamId)setSelectedTeam(teamId);};
  const market=[...(universe.marketHistory||[])].filter((move)=>move.year===universe.year).sort((a,b)=>marketSort==='Rarity'?(RARITY_ORDER[getDriver(universe,b.driverId)?.rarity]-RARITY_ORDER[getDriver(universe,a.driverId)?.rarity])||((b.to?.salary||0)-(a.to?.salary||0)):marketSort==='New salary'?(b.to?.salary||0)-(a.to?.salary||0):marketSort==='Age'?(getDriver(universe,a.driverId)?.age||99)-(getDriver(universe,b.driverId)?.age||99):b.year-a.year||String(b.id).localeCompare(a.id));
  const report=universe.preseasonReports?.[0];const filteredSpend=(report?.spendingChanges||[]).filter((item)=>tier==='All'||item.series===tier);const branding=(report?.brandingChanges||[]).filter((item)=>tier==='All'||item.series===tier);const spawned=(report?.spawned||[]).filter((item)=>tier==='All'||item.series===tier);const retired=(report?.retired||[]).filter((item)=>tier==='All'||item.lastSeries===tier);const sponsors=(report?.sponsorChanges||[]).filter((item)=>tier==='All'||item.series===tier);const staffMoves=(report?.staffChanges||[]).filter((item)=>tier==='All'||item.series===tier);
  const pressRoom=universe.drivers.flatMap((driver)=>(driver.mind?.press||[]).filter((item)=>item.year===universe.year).map((item)=>({driver,item}))).sort((a,b)=>(b.item.round||0)-(a.item.round||0)||(b.item.mention||0)-(a.item.mention||0));
  return <section className="page"><PageTitle eyebrow="THE PADDOCK" title="World Chronicle magazine" subtitle="Narrative for the big moments; clean market tables for every off-season change."/><div className="tab-row scroll"><Pill active={view==='Magazine'} onClick={()=>setView('Magazine')}>Magazine</Pill><Pill active={view==='Press'} onClick={()=>setView('Press')}>Press Room ({pressRoom.length})</Pill><Pill active={view==='Drivers'} onClick={()=>setView('Drivers')}>Driver Market ({market.length})</Pill><Pill active={view==='Staff'} onClick={()=>setView('Staff')}>Staff Market ({staffMoves.length})</Pill><Pill active={view==='Business'} onClick={()=>setView('Business')}>Business ({sponsors.length})</Pill><Pill active={view==='Pre-season'} onClick={()=>setView('Pre-season')}>Pre-season</Pill></div>
  {view==='Magazine'&&<><div className="tab-row scroll">{categories.map((item)=><Pill key={item} active={category===item} onClick={()=>setCategory(item)}>{item}</Pill>)}</div><div className="magazine-grid">{stories.map((story,index)=><article key={story.id} className={index===0?'lead':''} onClick={()=>openSubject(story)}><small>{story.category} · {yearLabel(story.year)}{story.round?` · R${story.round}`:''}</small><h2>{story.headline}</h2><p>{story.dek}</p><footer><span>{story.thread?.replaceAll('-',' ')||'world chronicle'}</span><b>Open subject ›</b></footer></article>)}</div></>}
  {view==='Drivers'&&<><div className="market-controls"><span>Sort market</span><select value={marketSort} onChange={(event)=>setMarketSort(event.target.value)}><option>Newest</option><option>Rarity</option><option>New salary</option><option>Age</option></select></div>{market.length?<div className="market-list">{market.map((move)=>{const driver=getDriver(universe,move.driverId);const fromTeam=getTeam(universe,move.from?.teamId);const toTeam=getTeam(universe,move.to?.teamId);return <button key={move.id} onClick={()=>setSelectedDriver(move.driverId)}><div className="market-driver"><Flag driver={driver}/><RarityTag rarity={driver?.rarity}/><span><b>{move.driverName}</b><small>{driver?.age||'—'} years · ability {driver?currentRating(driver):'—'} · happiness {driver?.happiness?.overall||'—'}</small></span></div><div className="market-route"><span><SeriesTag series={move.from?.series} role={move.from?.role}/><SeatBadge seat={move.from?.seat} team={fromTeam}/><b>{move.from?.teamName}</b><small>{money(move.from?.salary)}</small></span><strong>→</strong><span><SeriesTag series={move.to?.series} role={move.to?.role}/><SeatBadge seat={move.to?.seat} team={toTeam}/><b>{move.to?.teamName}</b><small>{money(move.to?.salary)}</small></span></div><small className="market-reason">{move.reason}</small></button>})}</div>:<Empty title="The first market has not opened" body="Complete the season and begin the next year."/>}</>}
  {view==='Staff'&&<>{report?<><TierFilter tier={tier} setTier={setTier}/><div className="change-table"><div><b>Person</b><b>Role</b><b>From</b><b>To</b><b>Salary</b></div>{staffMoves.map((move)=>{const staff=getStaff(universe,move.staffId);return <button key={move.id} onClick={()=>setSelectedStaff(move.staffId)}><span><RarityTag rarity={move.rarity}/><b>{move.name}</b></span><span>{move.role}</span><span>{move.fromTeamName}</span><span>{move.toTeamName}</span><span>{money(move.oldSalary)} → {money(move.newSalary)}</span></button>})}</div>{!staffMoves.length&&<Empty title="No staff moves" body="The current winter produced no staff changes for this tier."/>}</>:<Empty title="No staff market yet" body="Move to the next season to create the first staff market."/>}</>}
  {view==='Business'&&<>{report?<><TierFilter tier={tier} setTier={setTier}/><div className="change-table sponsor-table"><div><b>Team</b><b>Action</b><b>Previous sponsor</b><b>New sponsor</b><b>Income change</b></div>{sponsors.map((item,index)=><button key={`${item.teamId}-${index}`} onClick={()=>setSelectedTeam(item.teamId)}><span><SeriesTag series={item.series}/><b>{item.teamName}</b></span><span>{item.type}</span><span>{item.oldSponsorName}</span><span>{item.newSponsorName}</span><span>{money(item.oldIncome)} → {money(item.newIncome)}</span></button>)}</div>{!sponsors.length&&<Empty title="No sponsor changes" body="No sponsor changed or renewed in this tier during the latest winter."/>}</>:<Empty title="No business report yet" body="Move to the next season to create sponsor renewals and replacements."/>}</>}
  {view==='Pre-season'&&<>{report?<><div className="preseason-head"><div><small>PRE-SEASON {yearLabel(report.year)}</small><h2>Winter changes across the universe</h2></div><TierFilter tier={tier} setTier={setTier}/></div><Panel title="Changes in annual spending" eyebrow="PREVIOUS → CURRENT"><div className="spending-table"><div><b>Tier</b><b>Team</b><b>Previous</b><b>Current</b><b>Change</b></div>{filteredSpend.map((item)=><button key={item.teamId} onClick={()=>setSelectedTeam(item.teamId)}><SeriesTag series={item.series}/><span>{item.teamName}</span><b>{money(item.previous)}</b><b>{money(item.current)}</b><em className={item.delta<0?'negative':''}>{item.delta>=0?'+':''}{money(item.delta)}</em></button>)}</div></Panel><div className="two-col"><Panel title="Branding changes" eyebrow="MAIN IDENTITY">{branding.length?<div className="preseason-list">{branding.map((item)=><button key={item.teamId} onClick={()=>setSelectedTeam(item.teamId)}><SeriesTag series={item.series}/><span><b>{item.fromName}</b><small>became</small></span><strong>→</strong><span><b>{item.toName}</b></span></button>)}</div>:<p>No main-brand changes in this tier.</p>}</Panel><Panel title="New drivers" eyebrow="SPAWNED INTO THE UNIVERSE">{spawned.length?<div className="preseason-people">{spawned.map((item)=>{const driver=getDriver(universe,item.driverId);return <button key={item.driverId} onClick={()=>setSelectedDriver(item.driverId)}><Flag driver={driver}/><RarityTag rarity={item.rarity}/><span><b>{item.name}</b><small>{item.age} · {item.series} · {getTeam(universe,item.teamId)?.name||'Free agent'}</small></span></button>})}</div>:<p>No new drivers in this tier.</p>}</Panel></div><Panel title="Retirements" eyebrow="CAREERS CLOSED">{retired.length?<div className="preseason-people">{retired.map((item)=>{const driver=getDriver(universe,item.driverId);return <button key={item.driverId} onClick={()=>setSelectedDriver(item.driverId)}><Flag driver={driver}/><RarityTag rarity={item.rarity}/><span><b>{item.name}</b><small>{item.age} · last raced in {item.lastSeries}</small></span></button>})}</div>:<p>No retirements in this tier.</p>}</Panel></>:<Empty title="No pre-season report yet" body="Complete the season and move to the next year."/>}</>}
  </section>
}

function TierFilter({tier,setTier}){return <div className="tab-row scroll"><Pill active={tier==='All'} onClick={()=>setTier('All')}>All</Pill>{SERIES_ORDER.map((item)=><Pill key={item} active={tier===item} onClick={()=>setTier(item)}>{item}</Pill>)}</div>}
function LeaderCard({title,rows,value,onOpen}){return <Panel title={title} eyebrow="TOP FIVE"><div className="event-leaders">{rows.map((driver,index)=><button key={driver.id} onClick={()=>onOpen(driver.id)}><strong>{index+1}</strong><Flag driver={driver}/><span><b>{driver.name}</b><small>{value(driver)}</small></span></button>)}</div></Panel>}


function Almanac({universe,setSelectedDriver,setSelectedTeam}){const [tab,setTab]=useState('GOAT');const [mode,setMode]=useState('F1');const goats=goatLeaderboard(universe,mode).slice(0,50);return <section className="page"><PageTitle eyebrow="PERMANENT HISTORY" title="Almanac" subtitle="Titles, wins, points, lineages, seasons and careers remain navigable as the universe grows."/><div className="tab-row">{['GOAT','Seasons','Team Lineage','Records'].map((item)=><Pill key={item} active={tab===item} onClick={()=>setTab(item)}>{item}</Pill>)}</div>{tab==='GOAT'&&<><div className="tab-row compact">{['F1','All Motorsport','Peak','Longevity'].map((item)=><Pill key={item} active={mode===item} onClick={()=>setMode(item)}>{item}</Pill>)}</div><Panel title="Driver GOAT index" eyebrow={`${mode.toUpperCase()} FORMULA`}><div className="goat-table">{goats.map((driver,index)=><button key={driver.id} onClick={()=>setSelectedDriver(driver.id)}><strong>{index+1}</strong><Flag driver={driver}/><RarityTag rarity={driver.rarity}/><span><b>{driver.name}</b><small>{driver.career.titles} F1 titles · {driver.career.f1Wins} wins · {driver.career.seriesTitles} other titles</small></span><em>{driver.goat.toFixed(1)}</em></button>)}</div></Panel></>}{tab==='Seasons'&&(universe.seasonArchive.length?<div className="history-grid">{[...universe.seasonArchive].reverse().map((season)=><Panel key={season.year} title={`${yearLabel(season.year)} season`} eyebrow={`${season.calendar.length} GRANDS PRIX`}><div className="history-champions"><span><small>F1 DRIVER</small><b>{season.championName}</b></span><span><small>F1 TEAM</small><b>{season.constructorName}</b></span></div><div className="series-champions">{SERIES_ORDER.slice(1).map((series)=><span key={series}><b>{series}</b>{season.series?.[series]?.championName||'—'}</span>)}</div></Panel>)}</div>:<Empty title="No archived seasons" body="Complete the current year to create the first permanent season record."/>)}{tab==='Team Lineage'&&<div className="lineage-grid">{universe.teams.map((team)=><button key={team.id} onClick={()=>setSelectedTeam(team.id)}><LiveryCar team={team} universe={universe}/><h3>{team.name}</h3>{team.lineage.map((entry)=><span key={`${entry.year}-${entry.name}`}><b>{yearLabel(entry.year)}</b>{entry.name} · {entry.owner}</span>)}</button>)}</div>}{tab==='Records'&&<div className="record-card-grid"><LeaderCard title="Most F1 titles" rows={[...universe.drivers].sort((a,b)=>b.career.titles-a.career.titles).slice(0,5)} value={(driver)=>`${driver.career.titles} titles`} onOpen={setSelectedDriver}/><LeaderCard title="Most F1 wins" rows={[...universe.drivers].sort((a,b)=>b.career.f1Wins-a.career.f1Wins).slice(0,5)} value={(driver)=>`${driver.career.f1Wins} wins`} onOpen={setSelectedDriver}/><LeaderCard title="Most F1 starts" rows={[...universe.drivers].sort((a,b)=>b.career.f1Starts-a.career.f1Starts).slice(0,5)} value={(driver)=>`${driver.career.f1Starts} starts`} onOpen={setSelectedDriver}/><LeaderCard title="Most F1 poles" rows={[...universe.drivers].sort((a,b)=>b.career.f1Poles-a.career.f1Poles).slice(0,5)} value={(driver)=>`${driver.career.f1Poles} poles`} onOpen={setSelectedDriver}/></div>}</section>}

function More({universe,setUniverse,week,month,season,nextYear,busy,saveNow,saveAndExit,currentSlot}){const update=(key,value)=>setUniverse((previous)=>({...previous,settings:{...previous.settings,[key]:value}}));return <section className="page"><PageTitle eyebrow={`UNIVERSE SLOT ${currentSlot} · SCHEMA V${SCHEMA_VERSION}`} title="Universe controls" subtitle="Save management, global simulation cadence and commissioner settings."/><div className="two-col"><Panel title="Save and simulation" eyebrow="UNIVERSE"><div className="button-stack"><button className="primary" onClick={saveNow}>Save now</button><button className="outline" onClick={()=>exportUniverse(universe)}>Export JSON</button><button className="outline" onClick={saveAndExit}>Save and return to slots</button>{universe.phase==='Season complete'?<button className="primary" onClick={nextYear} disabled={busy}>Run off-season and begin {yearLabel(universe.year+1)}</button>:<><button onClick={week} disabled={busy}>Simulate 1 week</button><button onClick={month} disabled={busy}>Simulate 4 weeks</button><button className="danger" onClick={season} disabled={busy}>Simulate all competitions to year end</button></>}</div></Panel><Panel title="Commissioner settings" eyebrow="WORLD DYNAMISM"><Setting label="Calendar churn" value={universe.settings.calendarChurn} options={['Locked','Conservative','Aggressive']} onChange={(value)=>update('calendarChurn',value)}/><Setting label="Team dynamism" value={universe.settings.teamDynamism} options={['Static','Plausible']} onChange={(value)=>update('teamDynamism',value)}/><Setting label="Protected identities" value={universe.settings.authenticLock?'On':'Off'} options={['On','Off']} onChange={(value)=>update('authenticLock',value==='On')}/><Setting label="Autosave" value={universe.settings.autoSave?'On':'Off'} options={['On','Off']} onChange={(value)=>update('autoSave',value==='On')}/></Panel></div><Panel title="Systems active" eyebrow="BUILD COVERAGE"><div className="coverage">{['Page-based browser navigation and back history','All drivers and teams across six competitions','1-week, 4-week and full-year world simulation','1–10 facilities with annual decay and investment','Driver hierarchy based on quality, tenure, experience and success','Named race engineer assigned to Driver 1 and Driver 2','Rarity-colored transferable staff','Effective current skills separated from raw base talent','Weather, circuit DNA, finances, transfers, history and GOAT'].map((item)=><span key={item}>✓ {item}</span>)}</div></Panel></section>}

function Setting({label,value,options,onChange}){return <label className="setting"><span><b>{label}</b><small>Current: {value}</small></span><select value={value} onChange={(event)=>onChange(event.target.value)}>{options.map((option)=><option key={option}>{option}</option>)}</select></label>}

function lapDisplay(value){if(value==null)return'—';if(typeof value==='string')return value;const minutes=Math.floor(value/60);return `${minutes}:${(value%60).toFixed(3).padStart(6,'0')}`}
function countEventAppearances(records){const counts=new Map();records.forEach((record)=>{(record.sessions?.R?.rows||record.podium||[]).forEach((row)=>{const id=row.driverId;if(id)counts.set(id,(counts.get(id)||0)+1)})});return [...counts.entries()].sort((a,b)=>b[1]-a[1])}
function countLeaders(records,key,limit=10){const counts=new Map();records.forEach((record)=>{const id=record[key];if(id)counts.set(id,(counts.get(id)||0)+1);});return [...counts.entries()].sort((a,b)=>b[1]-a[1]).slice(0,limit)}
function circuitIdentity(event){const traits=event?.traits||{};const ranked=[['High-speed car',traits.high],['Technical / low-speed car',traits.low],['Power and low drag',traits.straight],['Tyre management',traits.tyre],['Street-circuit agility',traits.street]].sort((a,b)=>(b[1]||0)-(a[1]||0));const driver=ranked[0]?.[0]==='High-speed car'?'High-speed specialists':ranked[0]?.[0]==='Technical / low-speed car'?'Technical and precision drivers':ranked[0]?.[0]==='Power and low drag'?'Late brakers and power-circuit specialists':ranked[0]?.[0]==='Tyre management'?'Tyre whisperers':'Street-circuit specialists';return{car:ranked[0]?.[0]||'Balanced car',driver}}
function EventResultTable({universe,session,openDriver}){
  const rows=session?.rows||[];if(!rows.length)return <Empty title="No classification" body="This session has not been completed in the current season."/>;
  return <div className="event-table"><div className="event-table-head"><span>Pos</span><span>Driver</span><span>Team</span><span>Time / gap</span><span>Pts</span></div>{rows.map((row,index)=>{const driver=getDriver(universe,row.driverId);const team=getTeam(universe,row.teamId||driver?.teamId);const points=row.points||0;const bonus=row.bonusPoints||0;const base=row.basePoints??Math.max(0,points-bonus);return <button key={`${session.key}-${row.driverId}-${index}`} onClick={()=>openDriver(driver?.id)}><strong>{row.position||index+1}</strong><span className="event-driver"><Flag driver={driver}/><SeatBadge driver={driver} team={team}/><b>{driver?.name||'Unknown'}</b><RarityTag rarity={driver?.rarity}/></span><span><TeamStripe team={team}/>{team?.name||'—'}</span><em>{row.status&&row.status!=='Running'?row.gap||row.status:row.gap||lapDisplay(row.time)}</em><b className="points-cell">{points}{bonus>0&&<small>{base} + {bonus} FL</small>}</b></button>})}</div>;
}

function EventPage({universe,selection,back,openDriver,openTeam}){
  const [tab,setTab]=useState('Overview');const [sessionKey,setSessionKey]=useState('FP1');const series=selection.series||'F1';const calendar=competitionCalendar(universe,series);const event=calendar.find((item)=>item.id===selection.eventId)||calendar.find((item)=>(item.circuitId||item.id)===selection.circuitId);const circuitId=selection.circuitId||event?.circuitId||event?.id;
  const records=[...(universe.eventArchive||[]),...competitionResults(universe,series)].filter((record)=>record.series===series&&(record.circuitId===circuitId||record.eventId===selection.eventId)).sort((a,b)=>b.year-a.year);const latest=records[0];const current=records.find((record)=>record.year===universe.year);const identity=circuitIdentity(event||latest?.event);
  const winLeaders=countLeaders(records,'winnerId',10);const poleLeaders=countLeaders(records,'poleId',10);const teamLeaders=countLeaders(records,'teamWinnerId',10);const fastest=records.filter((record)=>record.fastestLapTime).sort((a,b)=>a.fastestLapTime-b.fastestLapTime).slice(0,3);const sessionKeys=['FP1','FP2','FP3','SQ1','SQ2','SQ3','S','Q1','Q2','Q3','R'].filter((key)=>current?.sessions?.[key]);
  return <section className="page detail-page"><button className="back-link" onClick={back}>← Back</button><div className="event-sheet page-sheet"><div className="event-hero"><div><SeriesTag series={series}/><small>ROUND {event?.round||latest?.round||'—'} · {event?.city||latest?.event?.city}</small><h1>{event?.name||latest?.event?.name||'Race event'}</h1><p><Flag country={event?.country||latest?.event?.country}/>{event?.country||latest?.event?.country} · {event?.rain??latest?.event?.rain}% rain baseline · {event?.temp??latest?.event?.temp}°C climate baseline</p></div><div className="event-dna"><b>{identity.car}</b><span>Favoured car profile</span><b>{identity.driver}</b><span>Favoured driver profile</span></div></div><div className="tab-row event-tabs">{['Overview','Current Year','History','Stats'].map((item)=><Pill key={item} active={tab===item} onClick={()=>setTab(item)}>{item}</Pill>)}</div>
  {tab==='Overview'&&<div className="event-overview"><Panel title="Most recent podium" eyebrow={latest?`${yearLabel(latest.year)} ${series}`:'NO RESULT'}>{latest?<div className="podium-list">{latest.podium?.map((podium)=>{const driver=getDriver(universe,podium.driverId);const team=getTeam(universe,podium.teamId);return <button key={podium.driverId} onClick={()=>openDriver(driver?.id)}><strong>P{podium.position}</strong><Flag driver={driver}/><SeatBadge driver={driver} team={team}/><span><b>{driver?.name}</b><small>{team?.name}</small></span></button>})}<div className="overview-facts"><span><small>TEAM WINNER</small><button onClick={()=>openTeam(latest.teamWinnerId)}>{getTeam(universe,latest.teamWinnerId)?.name||'—'}</button></span><span><small>POLE</small><button onClick={()=>openDriver(latest.poleId)}>{getDriver(universe,latest.poleId)?.name||'—'}</button></span></div></div>:<Empty title="No completed edition" body="Complete this event to create its first podium and records."/>}</Panel><Panel title="Circuit profile" eyebrow="PERFORMANCE DNA"><div className="skill-grid">{Object.entries(event?.traits||latest?.event?.traits||{}).map(([key,value])=><Progress key={key} label={key} value={value}/>)}</div><p className="model-note">The circuit changes the competitive order. Car architecture, engine power, reliability, tyre life, driver specialty and weather are all weighted differently here.</p></Panel><Panel title="Historical winners" eyebrow="TOP THREE"><div className="event-leaders">{winLeaders.length?winLeaders.slice(0,3).map(([id,count],index)=><button key={id} onClick={()=>openDriver(id)}><strong>{index+1}</strong><Flag driver={getDriver(universe,id)}/><span><b>{getDriver(universe,id)?.name||'Historic driver'}</b><small>{count} wins</small></span></button>):<p>No historical winners yet.</p>}</div></Panel><Panel title="Pole specialists" eyebrow="TOP THREE"><div className="event-leaders">{poleLeaders.length?poleLeaders.slice(0,3).map(([id,count],index)=><button key={id} onClick={()=>openDriver(id)}><strong>{index+1}</strong><Flag driver={getDriver(universe,id)}/><span><b>{getDriver(universe,id)?.name||'Historic driver'}</b><small>{count} poles</small></span></button>):<p>No pole history yet.</p>}</div></Panel><Panel title="Fastest laps ever" eyebrow="TOP THREE"><div className="event-leaders">{fastest.length?fastest.map((record,index)=><button key={`${record.year}-${record.fastestLapDriverId}`} onClick={()=>openDriver(record.fastestLapDriverId)}><strong>{index+1}</strong><Flag driver={getDriver(universe,record.fastestLapDriverId)}/><span><b>{getDriver(universe,record.fastestLapDriverId)?.name||'Historic driver'}</b><small>{yearLabel(record.year)} · {lapDisplay(record.fastestLapTime)}</small></span></button>):<p>No fastest laps yet.</p>}</div></Panel></div>}
  {tab==='Current Year'&&<>{current?<><div className="tab-row scroll session-tabs">{sessionKeys.map((key)=><Pill key={key} active={sessionKey===key} onClick={()=>setSessionKey(key)}>{current.sessions[key]?.label||key}</Pill>)}</div><Panel title={current.sessions[sessionKey]?.label||sessionKey} eyebrow={`${yearLabel(universe.year)} · ${current.sessions[sessionKey]?.weather||'CONDITIONS'}${current.sessions[sessionKey]?.temperature!=null?` · ${current.sessions[sessionKey].temperature}°C`:''}${current.sessions[sessionKey]?.thermal&&current.sessions[sessionKey].thermal!=='Normal'?` · ${current.sessions[sessionKey].thermal}`:''}`}><EventResultTable universe={universe} session={current.sessions[sessionKey]} openDriver={openDriver}/></Panel></>:<Empty title={`No completed ${yearLabel(universe.year)} edition`} body="After this race is finished, every Friday session, Q1, Q2, Q3 and the race will appear here with full times and points."/>}</>}
  {tab==='History'&&<Panel title="Edition by edition" eyebrow={`${series} HISTORY`}><div className="event-history-table"><div><b>Year</b><b>Winner / team</b><b>Second</b><b>Third</b><b>Fastest lap</b></div>{records.map((record)=>{const first=getDriver(universe,record.winnerId);const second=getDriver(universe,record.podium?.[1]?.driverId);const third=getDriver(universe,record.podium?.[2]?.driverId);const fast=getDriver(universe,record.fastestLapDriverId);return <div key={record.id}><strong>{yearLabel(record.year)}</strong><span><b>{first?.name||'—'}</b><small>{getTeam(universe,record.teamWinnerId)?.name||'—'}</small></span><span>{second?.name||'—'}</span><span>{third?.name||'—'}</span><span>{fast?.name||'—'}<small>{lapDisplay(record.fastestLapTime)}</small></span></div>})}</div></Panel>}
  {tab==='Stats'&&<div className="event-overview"><Panel title="Most appearances" eyebrow="TOP FIVE"><div className="event-leaders">{countEventAppearances(records).slice(0,5).map(([id,count],index)=><button key={id} onClick={()=>openDriver(id)}><strong>{index+1}</strong><Flag driver={getDriver(universe,id)}/><span><b>{getDriver(universe,id)?.name||'Historic driver'}</b><small>{count} starts</small></span></button>)}</div></Panel><Panel title="Most wins" eyebrow="TOP FIVE"><div className="event-leaders">{winLeaders.slice(0,5).map(([id,count],index)=><button key={id} onClick={()=>openDriver(id)}><strong>{index+1}</strong><Flag driver={getDriver(universe,id)}/><span><b>{getDriver(universe,id)?.name||'Historic driver'}</b><small>{count} victories</small></span></button>)}</div></Panel><Panel title="Most poles" eyebrow="TOP FIVE"><div className="event-leaders">{poleLeaders.slice(0,5).map(([id,count],index)=><button key={id} onClick={()=>openDriver(id)}><strong>{index+1}</strong><Flag driver={getDriver(universe,id)}/><span><b>{getDriver(universe,id)?.name||'Historic driver'}</b><small>{count} poles</small></span></button>)}</div></Panel><Panel title="Fastest laps" eyebrow="TOP FIVE"><div className="event-leaders">{countLeaders(records,'fastestLapDriverId',5).map(([id,count],index)=><button key={id} onClick={()=>openDriver(id)}><strong>{index+1}</strong><Flag driver={getDriver(universe,id)}/><span><b>{getDriver(universe,id)?.name||'Historic driver'}</b><small>{count} fastest laps</small></span></button>)}</div></Panel><Panel title="Teams with most wins" eyebrow="TOP FIVE"><div className="event-leaders">{teamLeaders.slice(0,5).map(([id,count],index)=><button key={id} onClick={()=>openTeam(id)}><strong>{index+1}</strong><TeamStripe team={getTeam(universe,id)}/><span><b>{getTeam(universe,id)?.name||'Historic team'}</b><small>{count} wins</small></span></button>)}</div></Panel></div>}
  </div></section>
}

function CareerTrend({driver}){
  const curve=driver.careerCurve||[];if(!curve.length)return null;const width=Math.max(720,curve.length*46);const height=220;const min=Math.min(.68,...curve)-.02;const max=Math.max(1.02,...curve)+.02;const x=(index)=>curve.length===1?40:40+index*(width-80)/(curve.length-1);const y=(value)=>height-34-((value-min)/(max-min))*(height-70);const points=curve.map((value,index)=>`${x(index)},${y(value)}`).join(' ');
  return <div className="career-trend-wrap"><div className="career-trend-scroll"><svg className="career-trend" viewBox={`0 0 ${width} ${height}`} role="img" aria-label={`${driver.name} complete career multiplier trend`}><line x1="40" y1={height-34} x2={width-40} y2={height-34}/><polyline points={points}/>{curve.map((value,index)=><g key={index} className={index===driver.curveIndex?'current':''}><circle cx={x(index)} cy={y(value)} r={index===driver.curveIndex?7:4}/>{(index===0||index===driver.curveIndex||index===curve.length-1)&&<text x={x(index)} y={Math.max(18,y(value)-12)} textAnchor="middle">{Number(value).toFixed(2)}</text>}</g>)}</svg></div><div className="career-year-strip">{curve.map((value,index)=><div key={index} className={index===driver.curveIndex?'active':''}><small>Y{index+1} · age {driver.debutAge+index}</small><b>{Number(value).toFixed(3)}</b>{index===driver.curveIndex&&<span>Current</span>}</div>)}</div></div>;
}

function DriverCareerTable({universe,driver,history}){
  const currentSeries=driver.role==='Free agent'||driver.role==='Retired'?'FREE':driver.series;const liveStandings=SERIES_ORDER.includes(currentSeries)?driverStandings(universe,currentSeries):[];const livePosition=liveStandings.findIndex((item)=>item.id===driver.id);const liveTeam=getTeam(universe,driver.teamId);const currentRow=driver.active?{year:universe.year,series:currentSeries,teamId:driver.teamId,teamName:liveTeam?.name||(driver.role==='Free agent'?'Free agent':'—'),role:driver.role,seat:driver.seat,position:livePosition>=0?livePosition+1:null,points:driver.role==='Free agent'?0:driver.season.points||0,salary:driver.role==='Free agent'?0:driver.contract?.salary||0,wins:driver.role==='Free agent'?0:driver.season.wins||0,poles:driver.role==='Free agent'?0:driver.season.poles||0,podiums:driver.role==='Free agent'?0:driver.season.podiums||0,live:true}:null;
  const rows=[...(currentRow?[currentRow]:[]),...history].filter((row,index,array)=>index===array.findIndex((other)=>other.year===row.year&&other.series===row.series&&other.teamId===row.teamId&&other.role===row.role)).sort((a,b)=>b.year-a.year);
  const roleLabel=(row)=>row.role==='Free agent'||row.series==='FREE'?'Free agent':row.role==='Test driver'||row.role==='Reserve driver'?`Test (${row.seat||3})`:row.role==='Race driver'?`P${row.seat||'—'}`:row.role||'—';
  return rows.length?<div className="driver-career-table"><div className="driver-career-head"><b>Year</b><b>Team</b><b>Role</b><b>Competition</b><b>Pos</b><b>Points</b><b>Salary</b><b>Wins</b><b>Poles</b><b>Podiums</b></div>{rows.map((row,index)=><div key={`${row.year}-${row.series}-${row.teamId||'free'}-${index}`} className={row.live?'live-row':''}><strong>{yearLabel(row.year)}{row.live&&<small> LIVE</small>}</strong><span>{row.teamName||getTeam(universe,row.teamId)?.name||'Free agent'}</span><span>{roleLabel(row)}</span><span>{row.series==='FREE'?'Free agent':seriesName(row.series)}</span><em>{row.position?`P${row.position}`:'—'}</em><b>{row.points||0}</b><span>{money(row.salary||0)}</span><b>{row.wins||0}</b><b>{row.poles||0}</b><b>{row.podiums||0}</b></div>)}</div>:<p>No career seasons recorded yet.</p>;
}

function DriverCircuitWins({universe,driver}){
  const records=[...(universe.eventArchive||[]),...SERIES_ORDER.flatMap((series)=>competitionResults(universe,series)||[])].filter((record)=>record.winnerId===driver.id);const grouped=new Map();records.forEach((record)=>{const key=`${record.series}-${record.circuitId||record.eventId}`;const entry=grouped.get(key)||{name:record.event?.name||record.eventId,series:record.series,years:[]};if(!entry.years.includes(record.year))entry.years.push(record.year);grouped.set(key,entry);});const rows=[...grouped.values()].sort((a,b)=>b.years.length-a.years.length||a.name.localeCompare(b.name));return rows.length?<div className="circuit-win-grid">{rows.map((row)=><div key={`${row.series}-${row.name}`}><SeriesTag series={row.series}/><span><b>{row.name} × {row.years.length}</b><small>{row.years.sort((a,b)=>a-b).map(yearLabel).join(', ')}</small></span></div>)}</div>:<p>No race victories yet.</p>;
}


function teamSentimentText(score,teamName='this team'){
  if(score>=80)return `I love being at ${teamName}.`;
  if(score>=55)return `I really believe in ${teamName}.`;
  if(score>=25)return `${teamName} is fine for me.`;
  if(score<=-75)return `I hate how things are going at ${teamName}.`;
  if(score<=-50)return `I want to leave ${teamName}.`;
  if(score<=-25)return `I am frustrated with ${teamName}.`;
  return 'No strong thought about this team.';
}
function MindSubject({universe,kind,subjectId,openDriver,openTeam,openStaff}){
  if(kind==='team'){
    const team=getTeam(universe,subjectId);return team?<button className="inline-link" onClick={()=>openTeam?.(team.id)}>{team.name}</button>:<span>Former team</span>;
  }
  const driver=getDriver(universe,subjectId);if(driver)return <button className="inline-link" onClick={()=>openDriver?.(driver.id)}>{driver.name}</button>;
  const staff=getStaff(universe,subjectId);if(staff)return <button className="inline-link" onClick={()=>openStaff?.(staff.id)}>{staff.name}</button>;
  return <span>Unknown subject</span>;
}
function DriverPersonality({universe,driver,openDriver,openTeam,openStaff}){
  const personality=driver.personality||{};const mind=driver.mind||{};
  const thoughts=[...(mind.thoughts||[])].slice(0,16);const press=[...(mind.press||[])].slice(0,16);
  const teams=Object.entries(mind.teamSentiments||{}).map(([id,score])=>({team:getTeam(universe,id),score:Number(score||0)})).filter((item)=>item.team).sort((a,b)=>Math.abs(b.score)-Math.abs(a.score));
  const people=Object.entries(mind.people||{}).map(([id,score])=>({id,score:Number(score||0),driver:getDriver(universe,id),staff:getStaff(universe,id)})).filter((item)=>(item.driver||item.staff)&&Math.abs(item.score)>=12).sort((a,b)=>Math.abs(b.score)-Math.abs(a.score));
  const official=Object.values(mind.official||{}).filter((item)=>item.official).length;
  return <>
    <div className="personality-intro"><b>Personality changes relationships and stories—not lap time.</b><span>Traits decide how a driver interprets events, how likely private thoughts are to reach the press, and how quickly respect or conflict becomes an official paddock narrative.</span></div>
    <div className="trait-grid">
      <div className="trait-card"><small>Communication</small><b>{personality.communication||'Calm'}</b><span>How openly they speak.</span></div>
      <div className="trait-card"><small>Competitive ethics</small><b>{personality.ethics||'Pragmatic'}</b><span>How they interpret racing limits.</span></div>
      <div className="trait-card"><small>Temperament</small><b>{personality.temperament||'Composed'}</b><span>How emotion shapes conflict.</span></div>
      <div className="trait-card"><small>Social style</small><b>{personality.social||'Independent'}</b><span>How they relate to teammates and peers.</span></div>
    </div>
    <div className="mind-summary"><span><b>{thoughts.length}</b>private thoughts stored</span><span><b>{press.length}</b>press comments</span><span><b>{official}</b>official stances</span><span><b>{people.filter((item)=>item.score<=-25).length}</b>active conflicts</span></div>
    <div className="two-col">
      <Panel title="Thoughts about teams" eyebrow="THRESHOLD-BASED · PRIVATE">
        {teams.length?<div className="team-thought-grid">{teams.slice(0,8).map(({team,score})=><button key={team.id} className={relationshipClass(score)} onClick={()=>openTeam?.(team.id)}><TeamStripe team={team}/><span><b>{team.name}</b><small>{teamSentimentText(score,team.name)}</small></span><em>{score>0?'+':''}{Math.round(score)}</em></button>)}</div>:<p>No strong team attachment has formed yet.</p>}
      </Panel>
      <Panel title="Relationships" eyebrow="DRIVERS + TEAM LEADERSHIP">
        {people.length?<div className="relationship-list">{people.slice(0,10).map((item)=>{const person=item.driver||item.staff;const isDriver=Boolean(item.driver);return <button key={item.id} className={relationshipClass(item.score)} onClick={()=>isDriver?openDriver?.(person.id):openStaff?.(person.id)}>{isDriver?<Flag driver={person}/>:<Flag country={person.country}/>}<span><b>{person.name}</b><small>{isDriver?'Driver':person.role} · {relationshipLabel(item.score)}</small></span><em>{item.score>0?'+':''}{Math.round(item.score)}</em></button>})}</div>:<p>No meaningful paddock relationships have crossed a threshold yet.</p>}
      </Panel>
    </div>
    <Panel title="Private thought log" eyebrow="WHAT THE DRIVER CURRENTLY CARRIES">
      {thoughts.length?<div className="thought-list">{thoughts.map((thought)=><div key={thought.id} className={thought.tone||'neutral'}><div><small>{yearLabel(thought.year)} · R{thought.round||0} · PRIVATE</small><b>{thought.text}</b></div><span><MindSubject universe={universe} kind={thought.kind} subjectId={thought.subjectId} openDriver={openDriver} openTeam={openTeam} openStaff={openStaff}/><em>{thought.score>0?'+':''}{Math.round(thought.score||0)}</em></span></div>)}</div>:<p>No threshold thought has been triggered yet. Neutral feelings deliberately produce no thought.</p>}
    </Panel>
    <Panel title="Press record" eyebrow="REPETITION MAKES A STANCE OFFICIAL">
      <p className="model-note">A private thought only becomes public when the driver's communication style and temperament make them voice it. Two public repetitions of the same stance make it official. Repeated criticism can damage the relationship with the team principal and, in extreme cases, put a race seat at risk.</p>
      {press.length?<div className="press-list">{press.map((item)=><div key={item.id} className={item.tone||'neutral'}><span><small>{yearLabel(item.year)} · R{item.round||0} · mention #{item.mention||1}</small><b>{item.text}</b></span><span>{item.official&&<strong className="official-badge">OFFICIAL</strong>}<MindSubject universe={universe} kind={item.kind} subjectId={item.subjectId} openDriver={openDriver} openTeam={openTeam} openStaff={openStaff}/></span></div>)}</div>:<p>Nothing from the private thought log has reached the media yet.</p>}
    </Panel>
  </>;
}

function DriverPage({universe,driver,back,openTeam,openStaff,openDriver}){
  const [tab,setTab]=useState('Overview');
  if(!driver)return <section className="page"><Empty title="Driver not found" body="This career no longer exists in the active universe."/></section>;
  const team=getTeam(universe,driver.teamId);const engineer=getStaff(universe,driver.engineerId);const history=[...(driver.career.seasons||[])];const transfers=[...(driver.transferHistory||[])].slice(0,30);
  const resultsSeries=SERIES_ORDER.includes(driver.series)?driver.series:(driver.lastSeries||'F1');const seasonResults=(competitionResults(universe,resultsSeries)||[]).map((record)=>{const raceRow=record.sessions?.R?.rows?.find((row)=>row.driverId===driver.id);const sprintRow=record.sessions?.S?.rows?.find((row)=>row.driverId===driver.id);const q3=record.sessions?.Q3?.rows?.find((row)=>row.driverId===driver.id);const q2=record.sessions?.Q2?.rows?.find((row)=>row.driverId===driver.id);const q1=record.sessions?.Q1?.rows?.find((row)=>row.driverId===driver.id);const racePoints=raceRow?.points||0;const bonusPoints=raceRow?.bonusPoints||0;const basePoints=raceRow?.basePoints??Math.max(0,racePoints-bonusPoints);const sprintPoints=sprintRow?.points||0;return{record,row:raceRow,sprintRow,qualifying:q3||q2||q1,basePoints,bonusPoints,sprintPoints,totalPoints:racePoints+sprintPoints};}).filter((item)=>item.row||item.sprintRow);
  const accounted=seasonResults.reduce((sum,item)=>sum+item.totalPoints,0);const raceBase=seasonResults.reduce((sum,item)=>sum+item.basePoints,0);const sprintTotal=seasonResults.reduce((sum,item)=>sum+item.sprintPoints,0);const bonusTotal=seasonResults.reduce((sum,item)=>sum+item.bonusPoints,0);const pointDelta=(driver.season.points||0)-accounted;
  const lastCompleted=history.slice().sort((a,b)=>b.year-a.year)[0];const heroTeamText=team?.name||(driver.role==='Retired'?(lastCompleted?.teamName||'Retired'):(driver.role||'Free agent'));
  return <section className="page detail-page"><button className="back-link" onClick={back}>← Back</button><div className="profile-hero" style={{'--team':team?.primary||team?.color||SERIES_META[driver.series]?.color||'#555'}}><div><SeriesTag series={driver.series} role={driver.role}/><RarityTag rarity={driver.rarity}/><SeatBadge driver={driver} team={team}/></div><Flag driver={driver}/><h1>{driver.name}</h1><p>{driver.country} · {driver.age} years · {driver.style} · {driver.trackSpecialty}</p><div className="personality-chips"><span>{driver.personality?.communication||'Calm'}</span><span>{driver.personality?.ethics||'Pragmatic'}</span><span>{driver.personality?.temperament||'Composed'}</span><span>{driver.personality?.social||'Independent'}</span></div>{team?<button className="team-link" onClick={()=>openTeam(team.id)}><TeamStripe team={team}/>{team.name} · Driver {driver.seat}</button>:<span className="retired-team-label">{heroTeamText}</span>}</div>
  <div className="tab-row detail-tabs">{['Overview','Personality','Current Season','Career','Transfers'].map((item)=><Pill key={item} active={tab===item} onClick={()=>setTab(item)}>{item}</Pill>)}</div>
  {tab==='Overview'&&<><div className="profile-stats"><span><b>{currentRating(driver)}</b>Current ability</span><span><b>{driver.baseTalent}</b>Base ceiling</span><span><b>{careerMultiplier(driver).toFixed(3)}</b>Career year</span><span><b>{driver.annualForm.toFixed(3)}</b>Annual form</span><span><b>{driver.age-driver.debutAge+1}</b>Career Y</span><span><b>{driver.happiness?.overall||'—'}</b>Happiness</span></div><div className="two-col"><Panel title="Driver identity" eyebrow="ROLE + CONTRACT"><div className="details"><span><b>Team status</b>{driver.role==='Race driver'?`Driver ${driver.seat}`:driver.role}</span><span><b>Race engineer</b>{engineer?<button className="inline-link" onClick={()=>openStaff(engineer.id)}>{engineer.name} · {engineer.rarity}</button>:'—'}</span><span><b>Contract through</b>{driver.contract?.through?yearLabel(driver.contract.through):'—'}</span><span><b>Salary</b>{money(driver.contract?.salary||0)}</span><span><b>Salary demand</b>{money(driver.salaryDemand||0)}</span><span><b>Commercial</b>{driver.commercial}</span></div></Panel><Panel title="Happiness" eyebrow="TRANSFER PRESSURE"><div className="skill-grid"><Progress label="Overall" value={driver.happiness?.overall||60}/><Progress label="Role" value={driver.happiness?.role||60}/><Progress label="Results" value={driver.happiness?.results||60}/><Progress label="Salary" value={driver.happiness?.salary||60}/></div><div className="reason-tags">{(driver.happiness?.reasons||[]).map((reason)=><span key={reason}>{reason}</span>)}</div></Panel></div><Panel title="Current skills" eyebrow="EFFECTIVE NOW · RAW CEILING"><div className="numeric-skill-grid">{Object.keys(driver.skills||{}).map((key)=><div key={key}><span>{key.replace(/([A-Z])/g,' $1')}</span><b>{effectiveDriverSkill(driver,key)}</b><small>raw {driver.skills[key]}</small></div>)}</div></Panel><Panel title="Career evolution" eyebrow="FULL PRE-GENERATED CAREER"><p className="model-note">The line covers the complete planned career, including future decline. Rarity and raw talent stay fixed; the multiplier controls how much of that talent is available in each season.</p><CareerTrend driver={driver}/></Panel></>}
  {tab==='Personality'&&<DriverPersonality universe={universe} driver={driver} openDriver={openDriver} openTeam={openTeam} openStaff={openStaff}/>}
  {tab==='Current Season'&&<><div className="profile-stats"><span><b>{driver.season.points}</b>Championship pts</span><span><b>{accounted}</b>Accounted pts</span><span><b>{raceBase}</b>Race pts</span><span><b>{sprintTotal}</b>Sprint pts</span><span><b>{bonusTotal}</b>Bonus pts</span><span><b>{driver.season.wins}</b>Wins</span></div>{pointDelta!==0&&<div className="points-warning">Points audit: championship total differs from visible event results by {pointDelta>0?'+':''}{pointDelta}. This exposes any remaining accounting issue instead of hiding it.</div>}<Panel title={`${yearLabel(universe.year)} race log`} eyebrow={resultsSeries}><div className="driver-race-log expanded"><div><b>Round</b><b>Event</b><b>Qualifying</b><b>Race</b><b>Sprint</b><b>Bonus</b><b>Weekend pts</b></div>{seasonResults.map(({record,row,sprintRow,qualifying,bonusPoints,totalPoints})=><div key={record.id}><strong>{record.round}</strong><span>{record.event?.name||record.eventId}</span><span>{qualifying?`P${qualifying.position}`:'—'}</span><span>{row?(row.status&&row.status!=='Running'?row.status:`P${row.position}`):'—'}</span><span>{sprintRow?`P${sprintRow.position} · ${sprintRow.points||0}`:'—'}</span><span>{bonusPoints?`+${bonusPoints} FL`:'—'}</span><b>{totalPoints}</b></div>)}</div>{!seasonResults.length&&<Empty title="No races completed" body="Simulate this driver's competition to populate the current season log."/>}</Panel></>}
  {tab==='Career'&&<><div className="two-col"><Panel title="Career record" eyebrow="ALL SERIES"><div className="details"><span><b>F1 starts</b>{driver.career.f1Starts}</span><span><b>F1 wins</b>{driver.career.f1Wins}</span><span><b>F1 podiums</b>{driver.career.f1Podiums}</span><span><b>F1 titles</b>{driver.career.titles}</span><span><b>Other titles</b>{driver.career.seriesTitles}</span><span><b>F1 poles</b>{driver.career.f1Poles}</span></div></Panel><Panel title="Career timing" eyebrow="LIFECYCLE"><div className="details"><span><b>Debut age</b>{driver.debutAge}</span><span><b>Peak age</b>{driver.peakAge}</span><span><b>Planned retirement</b>{driver.debutAge+driver.careerCurve.length-1}</span><span><b>Planned length</b>{driver.careerCurve.length} years</span><span><b>Current year</b>Y{driver.curveIndex+1}</span></div></Panel></div><Panel title="Season history" eyebrow="YEAR · TEAM · ROLE · RESULTS"><DriverCareerTable universe={universe} driver={driver} history={history}/></Panel><Panel title="Circuits won" eyebrow="CAREER VICTORY MAP"><DriverCircuitWins universe={universe} driver={driver}/></Panel><Panel title="Career progression" eyebrow="ENTIRE CAREER CURVE"><CareerTrend driver={driver}/></Panel></>}
  {tab==='Transfers'&&<Panel title="Transfer history" eyebrow="MARKET">{transfers.length?<div className="transfer-history">{transfers.map((move)=><div key={move.id}><b>{yearLabel(move.year)}</b><span>{move.from.teamName} ({move.from.seat||'—'}) {move.from.series}, {money(move.from.salary)}</span><strong>→</strong><span>{move.to.teamName} ({move.to.seat||'—'}) {move.to.series}, {money(move.to.salary)}</span></div>)}</div>:<p>No recorded moves yet.</p>}</Panel>}
  </section>;
}

function facilityCostEstimate(value,series='F1'){const gain=Math.min(.5,Math.max(.05,10-(value||5)));const elite=Math.max(0,(value||5)-7);const base={F1:8,F2:8,F3:5,F4:3,FE:10,WEC:12}[series]||8;return Math.max(1,Math.round(base*gain*(1+Math.pow(elite,3)*2.15)))}
function FacilityCard({label,value,series='F1'}){return <div className="facility-card"><span>{label}</span><b>{Number(value||0).toFixed(1)}</b><i><em style={{width:`${clamp((value||0)*10,0,100)}%`}}/></i><small>Next +{Math.min(.5,Math.max(.05,10-(value||5))).toFixed(2)} ≈ {money(facilityCostEstimate(value,series))}</small></div>}
function TeamHistoryTable({universe,team,series}){
  const seasons=[...(team.career?.seasons||[])].reverse();
  if(!seasons.length)return <Empty title="No completed seasons" body="Finish the current season to create this organization's annual record."/>;
  return <div className="team-history-table"><div><b>Year</b><b>Name</b><b>Team director</b><b>Pos</b><b>Points</b><b>Engine</b><b>Driver 1</b><b>Driver 2</b></div>{seasons.map((season)=><div key={`${season.year}-${season.name}`}><strong>{yearLabel(season.year)}</strong><span>{season.name||team.name}</span><span>{season.teamPrincipalName||'—'}</span><b>P{season.position||'—'}</b><b>{season.points||0}</b><span>{season.engineName||getEngine(universe,season.engineId)?.name||'Spec engine'}</span><span>{season.pilots?.[0]?`${season.pilots[0].name} · ${season.pilots[0].points} pts · P${season.pilots[0].position}`:'—'}</span><span>{season.pilots?.[1]?`${season.pilots[1].name} · ${season.pilots[1].points} pts · P${season.pilots[1].position}`:'—'}</span></div>)}</div>
}

function TeamPage({universe,team,back,openDriver,openStaff}){
  const [tab,setTab]=useState('Overview');
  if(!team)return <section className="page"><Empty title="Team not found" body="This organization is not available."/></section>;
  const isF1=universe.teams.some((item)=>item.id===team.id);
  const series=isF1?'F1':team.series;
  const brand=isF1?getMainBrand(universe,team.mainBrandId):null;
  const drivers=universe.drivers.filter((driver)=>driver.teamId===team.id&&driver.role==='Race driver'&&driver.active).sort((a,b)=>(a.seat||9)-(b.seat||9));
  const tests=isF1?(team.testDriverIds||[]).map((id)=>getDriver(universe,id)).filter(Boolean):[];
  const staff=(team.staffIds||[]).map((id)=>getStaff(universe,id)).filter(Boolean);
  const principals=staff.filter((member)=>member.role==='Team Principal').sort((a,b)=>b.rating-a.rating);const technicalStaff=staff.filter((member)=>['Technical Director','Sporting Director'].includes(member.role)).sort((a,b)=>b.rating-a.rating);const strategists=staff.filter((member)=>member.role.includes('Strateg')).sort((a,b)=>b.rating-a.rating);const raceEngineers=staff.filter((member)=>member.role==='Race Engineer').sort((a,b)=>(a.assignedSeat||9)-(b.assignedSeat||9));const otherStaff=staff.filter((member)=>!principals.includes(member)&&!technicalStaff.includes(member)&&!strategists.includes(member)&&!raceEngineers.includes(member)).sort((a,b)=>b.rating-a.rating);
  const sponsors=(team.sponsorIds||[]).map((id)=>getSponsor(universe,id)).filter(Boolean);
  const carData=isF1?(team.car||{}):(team.carProfile||{});
  const carQuality=team.baseline||team.rating||avg(Object.values(carData));
  const finances=team.finances||{};
  const income=finances.totalIncome??finances.income??0;
  const expenses=finances.totalExpenses??finances.expenses??0;
  const seasons=team.career?.seasons||[];
  const titles=seasons.filter((season)=>season.position===1).length+(team.career?.constructorTitles||0);
  const wins=isF1?(team.career?.wins||0):seasons.reduce((sum,season)=>sum+(season.wins||0),0)+(team.wins||0);
  return <section className="page detail-page">
    <button className="back-link" onClick={back}>← Back</button>
    <div className="team-hero page-team-hero" style={{background:`linear-gradient(125deg,${team.primary||team.color||SERIES_META[series]?.color},#111 72%)`}}><div><SeriesTag series={series}/><small>{brand?`${brand.tier.toUpperCase()} MAIN BRAND · ${brand.country.toUpperCase()}`:(team.country||seriesName(series)).toUpperCase()}</small><h1>{team.name}</h1><p>{brand?`${brand.name} identity · ${getEngine(universe,team.engineId)?.name} power · Heritage ${team.heritage}`:`${SERIES_META[series]?.name} entrant · permanent universe organization`}</p></div>{isF1?<LiveryCar team={team} universe={universe}/>:<div className="feeder-team-mark" style={{'--team':team.color||SERIES_META[series]?.color}}>{team.short||series}</div>}</div>
    <div className="tab-row detail-tabs">{['Overview','Personnel','Finance','History'].map((item)=><Pill key={item} active={tab===item} onClick={()=>setTab(item)}>{item}</Pill>)}</div>
    {tab==='Overview'&&<><div className="profile-stats"><span><b>{Math.round(carQuality)}</b>Car</span><span><b>{isF1?(team.season?.points??0):(team.points??team.season?.points??0)}</b>Points</span><span><b>{wins}</b>Race wins</span><span><b>{titles}</b>Team titles</span><span><b>{money(finances.cash||0)}</b>Cash</span><span><b>{avg(Object.values(team.facilities||{})).toFixed(1)}</b>Facility avg</span></div><div className="two-col"><Panel title="Current drivers" eyebrow="TEAM HIERARCHY"><div className="people-list">{drivers.map((driver)=><button key={driver.id} onClick={()=>openDriver(driver.id)}><Flag driver={driver}/><SeatBadge driver={driver} team={team}/><RarityTag rarity={driver.rarity}/><span><b>{driver.name}</b><small>Driver {driver.seat} · ability {currentRating(driver)} · {driver.season.points} pts</small></span></button>)}</div></Panel><Panel title="Organization summary" eyebrow="IDENTITY"><div className="details"><span><b>Competition</b>{seriesName(series)}</span><span><b>Current name</b>{team.name}</span><span><b>Main brand</b>{brand?.name||'Independent entrant'}</span><span><b>Engine</b>{isF1?getEngine(universe,team.engineId)?.name||'—':'Spec engine'}</span><span><b>Years recorded</b>{seasons.length}</span><span><b>Projected balance</b>{money(finances.projectedBalance||0)}</span></div></Panel></div><Panel title="Facilities" eyebrow="1–10 · ELITE LEVELS COST EXPONENTIALLY MORE"><p className="model-note">Facilities decay every winter, with 9–10 level installations decaying fastest. Upgrading from 9.5 to 10 can consume a major team's entire surplus. Great facilities create a top car only when paired with strong technical leadership.</p><div className="facility-grid">{Object.entries(team.facilities||{}).map(([key,value])=><FacilityCard key={key} label={key.replace(/([A-Z])/g,' $1')} value={value} series={series}/>)}</div></Panel><Panel title="Car profile" eyebrow="CURRENT PACKAGE"><div className="skill-grid">{Object.entries(carData).map(([key,value])=><Progress key={key} label={key} value={value}/>)}</div></Panel></>}
    {tab==='Personnel'&&<><Panel title="Team principal" eyebrow="ORGANIZATION LEADER · DRIVER RECRUITMENT · SPONSORS · PERFORMANCE"><div className="staff-grid staff-clickable principal-grid">{principals.length?principals.map((member)=><button key={member.id} onClick={()=>openStaff(member.id)}><Flag country={member.country}/><RarityTag rarity={member.rarity}/><span><b>{member.name}</b><small>{member.specialty} · commercial {member.commercial} · sporting {member.sporting}</small></span><em>{member.rating}</em></button>):<p>No team principal assigned.</p>}</div></Panel><div className="two-col"><Panel title="Race drivers" eyebrow="TEAM HIERARCHY"><div className="people-list">{drivers.map((driver)=><button key={driver.id} onClick={()=>openDriver(driver.id)}><Flag driver={driver}/><SeatBadge driver={driver} team={team}/><RarityTag rarity={driver.rarity}/><span><b>{driver.name}</b><small>Driver {driver.seat} · current {currentRating(driver)} · joined {yearLabel(driver.teamJoinedYear||universe.year)}</small></span></button>)}</div></Panel>{isF1&&<Panel title="Test drivers" eyebrow="DEVELOPMENT + BACKUP"><div className="people-list">{tests.map((driver)=><button key={driver.id} onClick={()=>openDriver(driver.id)}><Flag driver={driver}/><SeatBadge driver={driver} team={team}/><RarityTag rarity={driver.rarity}/><span><b>{driver.name}</b><small>Feedback {effectiveDriverSkill(driver,'feedback')} · current {currentRating(driver)}</small></span></button>)}</div></Panel>}</div><Panel title="Technical and sporting staff" eyebrow="CAR QUALITY + OPERATIONS"><div className="staff-grid staff-clickable">{[...technicalStaff,...otherStaff].map((member)=><button key={member.id} onClick={()=>openStaff(member.id)}><Flag country={member.country}/><RarityTag rarity={member.rarity}/><span><b>{member.name}</b><small>{member.role} · {member.specialty}</small></span><em>{member.rating}</em></button>)}</div></Panel><Panel title="Strategy" eyebrow="RACE EXECUTION"><div className="staff-grid staff-clickable">{strategists.length?strategists.map((member)=><button key={member.id} onClick={()=>openStaff(member.id)}><Flag country={member.country}/><RarityTag rarity={member.rarity}/><span><b>{member.name}</b><small>{member.role} · strategy {member.strategy}</small></span><em>{member.rating}</em></button>):<p>No specialist strategist assigned.</p>}</div></Panel><Panel title="Race engineers" eyebrow="ONE ENGINEER PER RACE SEAT"><div className="staff-grid staff-clickable">{raceEngineers.length?raceEngineers.map((member)=>{const assigned=member.assignedDriverId?getDriver(universe,member.assignedDriverId):null;return <button key={member.id} onClick={()=>openStaff(member.id)}><Flag country={member.country}/><RarityTag rarity={member.rarity}/><span><b>{member.name}</b><small>Driver {member.assignedSeat||'—'}{assigned?` · ${assigned.name}`:' · unassigned'} · rating {member.rating}</small></span><em>{member.rating}</em></button>}):<p>No race engineers assigned.</p>}</div></Panel></>}
    {tab==='Finance'&&<><div className="profile-stats"><span><b>{money(finances.cash||0)}</b>Cash</span><span><b>{money(income)}</b>Revenue</span><span><b>{money(expenses)}</b>Expenses</span><span><b>{money(finances.projectedBalance||0)}</b>Net</span><span><b>{money(finances.facilityInvestment||0)}</b>Facilities</span><span><b>{finances.dealQuality||'—'}</b>Deal quality</span></div><div className="two-col"><Panel title="Financial structure" eyebrow="INCOME VS COSTS"><div className="finance-breakdown"><div className="income"><h4>Income</h4><span><b>{isF1?'Main brand':'Core funding'}</b>{money(finances.mainFunding??finances.income??0)}</span><span><b>{isF1?'Secondary sponsors':'Prize / commercial'}</b>{money(isF1?finances.secondarySponsorIncome:finances.prizeMoney)}</span>{isF1&&<span><b>Prize money</b>{money(finances.prizeMoney)}</span>}<span className="finance-total"><b>Total</b>{money(income)}</span></div><div className="cost"><h4>Costs</h4>{isF1&&<span><b>Drivers + tests</b>{money(finances.driverCost)}</span>}<span><b>Key staff</b>{money(finances.staffCost)}</span><span><b>Facility investment</b>{money(finances.facilityInvestment||0)}</span>{isF1&&<span><b>Development</b>{money(finances.developmentCost)}</span>}<span className="finance-total"><b>Total</b>{money(expenses)}</span></div></div></Panel>{isF1?<Panel title="Secondary sponsors" eyebrow="COUNTRY ACCESS">{sponsors.length?<div className="sponsor-grid">{sponsors.map((sponsor)=><div key={sponsor.id} style={{'--sponsor':sponsor.colors[0]}}><b>{sponsor.name}</b><span><Flag country={sponsor.country}/>{sponsor.country}</span><small>{sponsor.industry} · base {money(sponsor.value)}</small></div>)}</div>:<p>No secondary sponsors.</p>}</Panel>:<Panel title="Funding model" eyebrow={series}><div className="details"><span><b>Core support</b>{money(finances.mainFunding||0)}</span><span><b>Prize money</b>{money(finances.prizeMoney||0)}</span><span><b>Staff costs</b>{money(finances.staffCost||0)}</span><span><b>Facility spend</b>{money(finances.facilityInvestment||0)}</span></div></Panel>}</div></>}
    {tab==='History'&&<Panel title="Annual organization history" eyebrow="NAME · DIRECTOR · ENGINE · DRIVERS"><TeamHistoryTable universe={universe} team={team} series={series}/></Panel>}
  </section>;
}

function StaffCareerTable({universe,member}){
  const team=getTeam(universe,member.teamId);const series=team?(universe.teams.some((item)=>item.id===team.id)?'F1':team.series):null;const standings=series?teamStandings(universe,series):[];const teamPos=team?standings.findIndex((item)=>item.id===team.id):-1;const drivers=series?driverStandings(universe,series).filter((item)=>item.teamId===team?.id):[];const best=drivers[0];const finances=team?.finances||{};const live=team?{year:universe.year,series,teamId:team.id,teamName:team.name,role:member.role,salary:member.salary||0,teamRevenue:finances.totalIncome??finances.income??0,teamPosition:teamPos>=0?teamPos+1:null,teamPoints:team.points??team.season?.points??0,teamWins:team.wins??team.season?.wins??0,bestDriverName:best?.name||'—',bestDriverPosition:best?driverStandings(universe,series).findIndex((item)=>item.id===best.id)+1:null,bestDriverPoints:best?.season?.points||0,live:true}:null;const rows=[...(live?[live]:[]),...(member.careerSeasons||[])].sort((a,b)=>b.year-a.year);
  return rows.length?<div className="staff-career-table"><div className="staff-career-head"><b>Year</b><b>Competition</b><b>Team</b><b>Salary</b><b>Revenue</b><b>Team pos</b><b>Team pts</b><b>Best driver</b><b>Driver pos</b><b>Driver pts</b><b>Wins</b></div>{rows.map((row,index)=><div key={`${row.year}-${row.teamId}-${index}`} className={row.live?'live-row':''}><strong>{yearLabel(row.year)}{row.live&&<small> LIVE</small>}</strong><span>{row.series||'—'}</span><span>{row.teamName||getTeam(universe,row.teamId)?.name||'Free agent'}</span><span>{money(row.salary||0)}</span><span>{money(row.teamRevenue||0)}</span><em>{row.teamPosition?`P${row.teamPosition}`:'—'}</em><b>{row.teamPoints||0}</b><span>{row.bestDriverName||'—'}</span><em>{row.bestDriverPosition?`P${row.bestDriverPosition}`:'—'}</em><b>{row.bestDriverPoints||0}</b><b>{row.teamWins||0}</b></div>)}</div>:<p>No completed staff seasons yet.</p>;
}

function StaffPage({universe,member,back,openTeam,openDriver}){
  const [tab,setTab]=useState('Overview');if(!member)return <section className="page"><Empty title="Staff member not found" body="This staff record is unavailable."/></section>;const team=getTeam(universe,member.teamId);const driver=getDriver(universe,member.assignedDriverId);const seasons=member.careerSeasons||[];const totalRevenue=seasons.reduce((sum,row)=>sum+(row.teamRevenue||0),0);const totalPoints=seasons.reduce((sum,row)=>sum+(row.teamPoints||0),0);const bestFinish=seasons.filter((row)=>row.teamPosition).reduce((best,row)=>Math.min(best,row.teamPosition),99);const bestDriverFinish=seasons.filter((row)=>row.bestDriverPosition).reduce((best,row)=>Math.min(best,row.bestDriverPosition),99);const teamsWorked=new Set(seasons.map((row)=>row.teamId).filter(Boolean)).size+(team&&!seasons.some((row)=>row.teamId===team.id)?1:0);const principalRelations=member.role==='Team Principal'?Object.entries(member.relationships||{}).map(([driverId,score])=>({driver:getDriver(universe,driverId),score:Number(score||0)})).filter((item)=>item.driver).sort((a,b)=>Math.abs(b.score)-Math.abs(a.score)):[];
  return <section className="page detail-page"><button className="back-link" onClick={back}>← Back</button><div className="profile-hero staff-hero" style={{'--team':team?.primary||team?.color||'#555'}}><div><RarityTag rarity={member.rarity}/></div><Flag country={member.country}/><h1>{member.name}</h1><p>{member.role} · {member.specialty} · {member.age} years old</p>{team&&<button className="team-link" onClick={()=>openTeam(team.id)}><TeamStripe team={team}/>{team.name}</button>}</div><div className="tab-row detail-tabs">{['Overview','Career','Stats'].map((item)=><Pill key={item} active={tab===item} onClick={()=>setTab(item)}>{item}</Pill>)}</div>
  {tab==='Overview'&&<><div className="profile-stats"><span><b>{member.rating}</b>Rating</span><span><b>{member.rarity}</b>Rarity</span><span><b>{member.contractThrough?yearLabel(member.contractThrough):'—'}</b>Contract</span><span><b>{money(member.salary)}</b>Salary</span><span><b>{member.titles||0}</b>Titles</span><span><b>{member.wins||0}</b>Team wins</span></div><div className="two-col"><Panel title="Role skills" eyebrow="STAFF PROFILE"><div className="skill-grid"><Progress label="Commercial" value={member.commercial}/><Progress label="Technical" value={member.technical}/><Progress label="Sporting" value={member.sporting}/><Progress label="Strategy" value={member.strategy}/><Progress label="Ambition" value={member.ambition}/></div>{member.role==='Team Principal'&&<p className="model-note">The team principal influences driver recruitment, sponsor negotiation, overall team execution and contributes a smaller oversight bonus to car development.</p>}{member.role==='Technical Director'&&<p className="model-note">Technical quality has a direct effect on development targets and how effectively facilities translate into car performance.</p>}{member.role==='Race Engineer'&&<p className="model-note">Race engineer quality directly modifies the assigned driver's practice, qualifying and race execution.</p>}</Panel><Panel title="Current assignment" eyebrow="ORGANIZATION"><div className="details"><span><b>Team</b>{team?.name||'Free agent'}</span><span><b>Joined</b>{member.teamJoinedYear?yearLabel(member.teamJoinedYear):'—'}</span><span><b>Personality</b>{member.personality}</span>{member.role==='Race Engineer'&&<span><b>Assigned driver</b>{driver?<button className="inline-link" onClick={()=>openDriver(driver.id)}>Driver {member.assignedSeat}: {driver.name}</button>:'Unassigned'}</span>}</div></Panel></div><Panel title="Transfer history" eyebrow="STAFF MARKET">{member.history?.length?<div className="career-history">{member.history.slice().reverse().map((entry,index)=><div key={`${entry.year}-${index}`}><b>{yearLabel(entry.year)}</b><span>{getTeam(universe,entry.teamId)?.name||entry.teamId} · {entry.role}</span></div>)}</div>:<p>No prior transfer recorded.</p>}</Panel>{member.role==='Team Principal'&&<Panel title="Driver relationships" eyebrow="TEAM LEADERSHIP · RESPECT + CONFLICT">{principalRelations.length?<div className="relationship-list principal-relations">{principalRelations.slice(0,12).map(({driver:related,score})=><button key={related.id} className={relationshipClass(score)} onClick={()=>openDriver(related.id)}><Flag driver={related}/><span><b>{related.name}</b><small>{relationshipLabel(score)}{related.teamId===member.teamId?' · current team':''}</small></span><em>{score>0?'+':''}{Math.round(score)}</em></button>)}</div>:<p>No driver relationship has crossed a meaningful threshold yet.</p>}<p className="model-note">Repeated public criticism can turn an ordinary working relationship into an open leadership conflict. A severely damaged relationship can make a pre-season demotion to test driver possible when the team has a credible replacement.</p></Panel>}</>}
  {tab==='Career'&&<Panel title={`${member.role} career`} eyebrow="YEAR-BY-YEAR ORGANIZATION RESULTS"><StaffCareerTable universe={universe} member={member}/></Panel>}
  {tab==='Stats'&&<><div className="profile-stats"><span><b>{seasons.length+(team?1:0)}</b>Seasons</span><span><b>{teamsWorked}</b>Teams</span><span><b>{member.titles||0}</b>Titles</span><span><b>{member.wins||0}</b>Team wins</span><span><b>{bestFinish===99?'—':`P${bestFinish}`}</b>Best team finish</span><span><b>{bestDriverFinish===99?'—':`P${bestDriverFinish}`}</b>Best driver finish</span></div><div className="two-col"><Panel title="Career production" eyebrow="RECORDED SEASONS"><div className="details"><span><b>Total team points</b>{totalPoints}</span><span><b>Average revenue</b>{money(seasons.length?totalRevenue/seasons.length:0)}</span><span><b>Total revenue overseen</b>{money(totalRevenue)}</span><span><b>Current salary</b>{money(member.salary)}</span></div></Panel><Panel title="Role impact" eyebrow="SIMULATION MODEL"><div className="details"><span><b>Technical</b>{member.technical}</span><span><b>Sporting</b>{member.sporting}</span><span><b>Commercial</b>{member.commercial}</span><span><b>Strategy</b>{member.strategy}</span></div></Panel></div></>}
  </section>;
}


createRoot(document.getElementById('root')).render(<App/>);
